window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id":"yy-18921","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，减税降费政策落地，公交司机让企业真切感受到红利。","options":["发放","散发","释放","发射"],"answer":2,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选C。","__sub":"片段阅读"},{"id":"yy-18922","module":"yanyu","diff":1,"exam":"省考","prompt":"连日来，筑起生态安全屏障，科研人员让青山常在绿水长流。","options":["拴牢","筑牢","砌牢","锁牢"],"answer":1,"explanation":"「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选B。","__sub":"片段阅读"},{"id":"yy-18923","module":"yanyu","diff":3,"exam":"国考","prompt":"初秋时节，被动状态必须改变，税务干部用硬措施______了不利局面。","options":["回转","反转","倒转","扭转"],"answer":3,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选D。","__sub":"选词填空"},{"id":"yy-18924","module":"yanyu","diff":1,"exam":"事业编","prompt":"开春以来，城乡公共服务仍有落差，博物馆讲解员以实策逐步______差距。","options":["缩减","减小","缩小","减少"],"answer":2,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选C。","__sub":"选词填空"},{"id":"yy-18925","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，放宽准入激发创业热情，农技人员让创造活力。","options":["淌出","涌流","流出","涌出"],"answer":1,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选B。","__sub":"片段阅读"},{"id":"yy-18926","module":"yanyu","diff":3,"exam":"事业编","prompt":"入冬以来，改革到了深水区，快递员以钉钉子精神______工作局面。","options":["打开","揭开","掀开","翻开"],"answer":0,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选A。","__sub":"选词填空"},{"id":"yy-18927","module":"yanyu","diff":1,"exam":"国考","prompt":"岁末年初，市场细胞活跃起来，执法人员让经济肌体活力。","options":["装满","填满","充满","塞满"],"answer":2,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选C。","__sub":"片段阅读"},{"id":"yy-18928","module":"yanyu","diff":3,"exam":"国考","prompt":"入冬以来，一次次说到做到，环卫工人用行动______了群众的信任。","options":["赢得","换取","获得","博得"],"answer":0,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选A。","__sub":"选词填空"},{"id":"yy-18929","module":"yanyu","diff":2,"exam":"国考","prompt":"连日来，越是众声喧哗，越需要______共识，调解员把大家的心拢到一起。","options":["冻住","凝结","凝聚","凝固"],"answer":2,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选C。","__sub":"选词填空"},{"id":"yy-18930","module":"yanyu","diff":1,"exam":"医疗编","prompt":"一段时间以来，传统村落保护性开发，图书管理员既富了口袋，也______了乡愁。","options":["拘留","留住","截留","扣留"],"answer":1,"explanation":"「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选B。","__sub":"选词填空"},{"id":"yy-18931","module":"yanyu","diff":2,"exam":"事业编","prompt":"入冬以来，金杯银杯不如老百姓的口碑，教师把每件小事都当大事办。","options":["建立","树立","创立","设立"],"answer":1,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选B。","__sub":"片段阅读"},{"id":"yy-18932","module":"yanyu","diff":2,"exam":"医疗编","prompt":"入冬以来，订单排到明年，老党员发展的信心。","options":["倍增","加倍","倍加","倍受"],"answer":0,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选A。","__sub":"片段阅读"},{"id":"yy-18933","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，安全底线不可逾越，果农24小时轮班值守。","options":["看守","镇守","坚守","把守"],"answer":2,"explanation":"「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选C。","__sub":"片段阅读"},{"id":"yy-18934","module":"yanyu","diff":1,"exam":"教师编","prompt":"连日来，老旧小区加装电梯、增设车位，科研人员尽力______居民多样需求。","options":["充盈","满意","充足","满足"],"answer":3,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选D。","__sub":"选词填空"},{"id":"yy-18935","module":"yanyu","diff":2,"exam":"医疗编","prompt":"入冬以来，改革到了深水区，果农以钉钉子精神______工作局面。","options":["打开","翻开","揭开","掀开"],"answer":0,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选A。","__sub":"选词填空"},{"id":"yy-18936","module":"yanyu","diff":3,"exam":"省考","prompt":"岁末年初，营商环境就是生产力，程序员让企业成长有沃土。","options":["培植","厚植","培育","培养"],"answer":1,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选B。","__sub":"片段阅读"},{"id":"yy-18937","module":"yanyu","diff":2,"exam":"省考","prompt":"连日来，老厂房变身文创园，医护人员让工业遗存______新的活力。","options":["换发","焕新","焕发","更新"],"answer":2,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选C。","__sub":"选词填空"},{"id":"yy-18938","module":"yanyu","diff":1,"exam":"省考","prompt":"一段时间以来，卡脖子技术亟待攻坚，农技人员集中力量______一个个瓶颈。","options":["撞破","突破","冲破","捅破"],"answer":1,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选B。","__sub":"选词填空"},{"id":"yy-18939","module":"yanyu","diff":2,"exam":"事业编","prompt":"近年来，从受理到反馈全流程留痕，铁路养护工以数字化手段______管理闭环。","options":["圈画","构建","搭圈","构画"],"answer":1,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选B。","__sub":"选词填空"},{"id":"yy-18940","module":"yanyu","diff":3,"exam":"事业编","prompt":"今年以来，纪律规矩挺在前面，图书管理员始终______纪律底线。","options":["把守","严守","遵守","看守"],"answer":1,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选B。","__sub":"选词填空"},{"id":"yy-18941","module":"yanyu","diff":1,"exam":"省考","prompt":"岁末年初，手握核心技术专利，治沙工人创新的底气。","options":["更硬","更壮","更强","更足"],"answer":3,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选D。","__sub":"片段阅读"},{"id":"yy-18942","module":"yanyu","diff":1,"exam":"国考","prompt":"岁末年初，民生领域还有欠账，志愿者们列出清单逐项______短板。","options":["修补","贴补","补齐","补丁"],"answer":2,"explanation":"「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选C。","__sub":"选词填空"},{"id":"yy-18943","module":"yanyu","diff":3,"exam":"国考","prompt":"初秋时节，邻里纠纷无小事，果农用真心______一件件矛盾。","options":["消融","瓦解","解开","化解"],"answer":3,"explanation":"「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选D。","__sub":"选词填空"},{"id":"yy-18944","module":"yanyu","diff":3,"exam":"省考","prompt":"开春以来，众人的事情由众人商量，文旅部门把各方______到规划图上。","options":["归拢","聚拢","收拢","凝聚"],"answer":3,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选D。","__sub":"选词填空"},{"id":"yy-18945","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，民生实事清单公示上墙，乡村医生一件一件______承诺。","options":["兑现","达成","实现","完成"],"answer":0,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选A。","__sub":"选词填空"},{"id":"yy-18946","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，老厂房变身文创园，治沙工人让工业遗存______新的活力。","options":["焕发","换发","更新","焕新"],"answer":0,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选A。","__sub":"选词填空"},{"id":"yy-18947","module":"yanyu","diff":1,"exam":"教师编","prompt":"入冬以来，让监督机制长出牙齿，农技人员把制度笼子越扎越紧。","options":["修复","修葺","健全","修理"],"answer":2,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选C。","__sub":"片段阅读"},{"id":"yy-18948","module":"yanyu","diff":2,"exam":"医疗编","prompt":"初秋时节，靠山吃山靠水吃水，志愿者们因地制宜______资源优势。","options":["发展","发挥","施展","发扬"],"answer":1,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选B。","__sub":"选词填空"},{"id":"yy-18949","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，一年一度的民生大考结束，市场监管部门向群众______了温暖的答卷。","options":["上缴","递交","呈报","交出"],"answer":3,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。","__sub":"选词填空"},{"id":"yy-18950","module":"yanyu","diff":2,"exam":"医疗编","prompt":"盛夏时节，让监督机制长出牙齿，网格员把制度笼子越扎越紧。","options":["修理","修葺","健全","修复"],"answer":2,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选C。","__sub":"片段阅读"},{"id":"yy-18951","module":"yanyu","diff":3,"exam":"国考","prompt":"一段时间以来，发展为了人民，教师把一件件民生实事办到群众心坎上，持续______福祉。","options":["增进","增殖","增加","增添"],"answer":0,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选A。","__sub":"选词填空"},{"id":"yy-18952","module":"yanyu","diff":3,"exam":"国考","prompt":"今年以来，传统村落保护性开发，老党员既富了口袋，也______了乡愁。","options":["留住","截留","拘留","扣留"],"answer":0,"explanation":"「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选A。","__sub":"选词填空"},{"id":"yy-18953","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，数据孤岛必须连起来，民警下决心______部门间的壁垒。","options":["打破","打碎","砸破","击碎"],"answer":0,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选A。","__sub":"选词填空"},{"id":"yy-18954","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，被动状态必须改变，调解员用硬措施______了不利局面。","options":["倒转","反转","扭转","回转"],"answer":2,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选C。","__sub":"选词填空"},{"id":"yy-18955","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，万丈高楼平地起，驻村干部一锤一钎______发展基础。","options":["夯实","填实","砸实","踩实"],"answer":0,"explanation":"「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-18956","module":"yanyu","diff":1,"exam":"省考","prompt":"盛夏时节，几十年如一日，市场监管部门在平凡岗位上______着为民初心。","options":["保守","坚守","守卫","把守"],"answer":1,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选B。","__sub":"选词填空"},{"id":"yy-18957","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，誓师大会上，渔民精神斗志，誓言响彻训练场。","options":["高扬","高昂","昂扬","高涨"],"answer":2,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选C。","__sub":"片段阅读"},{"id":"yy-18958","module":"yanyu","diff":1,"exam":"国考","prompt":"初秋时节，越是爬坡过坎，越要______必胜信心，青年学子一步一个脚印向前走。","options":["坚强","坚定","坚决","坚持不懈"],"answer":1,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选B。","__sub":"选词填空"},{"id":"yy-18959","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，老工业基地涅槃重生，博物馆讲解员加快新旧动能步伐。","options":["变换","改换","转变","转换"],"answer":3,"explanation":"「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选D。","__sub":"片段阅读"},{"id":"yy-18960","module":"yanyu","diff":1,"exam":"事业编","prompt":"连日来，誓师大会上，广大建设者精神斗志，誓言响彻训练场。","options":["高昂","高扬","高涨","昂扬"],"answer":3,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选D。","__sub":"片段阅读"},{"id":"yy-18961","module":"yanyu","diff":1,"exam":"省考","prompt":"近年来，越是众声喧哗，越需要______共识，消防员把大家的心拢到一起。","options":["冻住","凝聚","凝固","凝结"],"answer":1,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选B。","__sub":"选词填空"},{"id":"yy-18962","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，每个孩子都有闪光点，青年学子善于______学生潜能。","options":["开采","挖掘","掘取","挖出"],"answer":1,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选B。","__sub":"选词填空"},{"id":"yy-18963","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，越是爬坡过坎，越要______必胜信心，驻村干部一步一个脚印向前走。","options":["坚决","坚持不懈","坚强","坚定"],"answer":3,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选D。","__sub":"选词填空"},{"id":"yy-18964","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，初心如磐，使命在肩，程序员把承诺落到一件件小事上。","options":["履行","践行","执行","旅行"],"answer":1,"explanation":"「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选B。","__sub":"片段阅读"},{"id":"yy-18965","module":"yanyu","diff":1,"exam":"事业编","prompt":"岁末年初，营商环境就是生产力，驻村干部让企业成长有沃土。","options":["培植","厚植","培育","培养"],"answer":1,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选B。","__sub":"片段阅读"},{"id":"yy-18966","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，越是爬坡过坎，越要______必胜信心，护林员一步一个脚印向前走。","options":["坚定","坚强","坚持不懈","坚决"],"answer":0,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选A。","__sub":"选词填空"},{"id":"yy-18967","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，城乡公共服务仍有落差，手工艺人以实策逐步______差距。","options":["减少","缩小","减小","缩减"],"answer":1,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选B。","__sub":"选词填空"},{"id":"yy-18968","module":"yanyu","diff":1,"exam":"国考","prompt":"盛夏时节，每一起案件都关乎群众对法治的信仰，广大建设者用公正裁判______正义。","options":["防御","护卫","捍卫","保卫"],"answer":2,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选C。","__sub":"选词填空"},{"id":"yy-18969","module":"yanyu","diff":3,"exam":"事业编","prompt":"连日来，订单排到明年，广大建设者发展的信心。","options":["倍加","倍受","倍增","加倍"],"answer":2,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选C。","__sub":"片段阅读"},{"id":"yy-18970","module":"yanyu","diff":2,"exam":"省考","prompt":"一段时间以来，改革到了深水区，社区工作者以钉钉子精神______工作局面。","options":["揭开","打开","掀开","翻开"],"answer":1,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选B。","__sub":"选词填空"},{"id":"yy-18971","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，誓师大会上，医护人员精神斗志，誓言响彻训练场。","options":["高昂","昂扬","高扬","高涨"],"answer":1,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选B。","__sub":"片段阅读"},{"id":"yy-18972","module":"yanyu","diff":2,"exam":"教师编","prompt":"这些年，老厂房变身文创园，医护人员让工业遗存______新的活力。","options":["焕发","焕新","更新","换发"],"answer":0,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选A。","__sub":"选词填空"},{"id":"yy-18973","module":"yanyu","diff":1,"exam":"国考","prompt":"今年以来，把风险挺在前面，科研人员织密织牢安全网。","options":["防范","提防","防备","防守"],"answer":0,"explanation":"「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选A。","__sub":"片段阅读"},{"id":"yy-18974","module":"yanyu","diff":3,"exam":"国考","prompt":"连日来，老旧小区加装电梯、增设车位，电力工人尽力______居民多样需求。","options":["满足","充足","充盈","满意"],"answer":0,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选A。","__sub":"选词填空"},{"id":"yy-18975","module":"yanyu","diff":1,"exam":"医疗编","prompt":"初秋时节，众人的事情由众人商量，驻村干部把各方______到规划图上。","options":["凝聚","聚拢","收拢","归拢"],"answer":0,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选A。","__sub":"选词填空"},{"id":"yy-18976","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，卡脖子技术亟待攻坚，调解员集中力量______一个个瓶颈。","options":["突破","捅破","冲破","撞破"],"answer":0,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。","__sub":"选词填空"},{"id":"yy-18977","module":"yanyu","diff":1,"exam":"医疗编","prompt":"这些年，老工业基地涅槃重生，税务干部加快新旧动能步伐。","options":["变换","转变","转换","改换"],"answer":2,"explanation":"「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选C。","__sub":"片段阅读"},{"id":"yy-18978","module":"yanyu","diff":2,"exam":"医疗编","prompt":"开春以来，几十年如一日，执法人员在平凡岗位上______着为民初心。","options":["把守","守卫","坚守","保守"],"answer":2,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选C。","__sub":"选词填空"},{"id":"yy-18979","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，城乡公共服务仍有落差，税务干部以实策逐步______差距。","options":["减小","减少","缩小","缩减"],"answer":2,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选C。","__sub":"选词填空"},{"id":"yy-18980","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，老旧小区加装电梯、增设车位，博物馆讲解员尽力______居民多样需求。","options":["充足","满足","满意","充盈"],"answer":1,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选B。","__sub":"选词填空"},{"id":"yy-18981","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，齐抓共管不是一句口号，护林员推动齐抓共管合力。","options":["成立","成型","形成","成形"],"answer":2,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选C。","__sub":"片段阅读"},{"id":"yy-18982","module":"yanyu","diff":3,"exam":"国考","prompt":"入冬以来，一网通办让数据多跑路，非遗传承人以流程再造______政务效能。","options":["拔高","提高","抬高","提升"],"answer":3,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选D。","__sub":"选词填空"},{"id":"yy-18983","module":"yanyu","diff":1,"exam":"国考","prompt":"一段时间以来，向存量要效益，执法人员为产业升级______新空间。","options":["开展","拓开","展开","拓展"],"answer":3,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选D。","__sub":"选词填空"},{"id":"yy-18984","module":"yanyu","diff":1,"exam":"省考","prompt":"盛夏时节，让监督机制长出牙齿，茶农把制度笼子越扎越紧。","options":["修葺","修理","修复","健全"],"answer":3,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选D。","__sub":"片段阅读"},{"id":"yy-18985","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，人才是创新的第一资源，电力工人把发展根基越培越厚。","options":["浇灌","培土","厚植","施肥"],"answer":2,"explanation":"「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选C。","__sub":"片段阅读"},{"id":"yy-18986","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，一次次说到做到，税务干部用行动______了群众的信任。","options":["换取","赢得","博得","获得"],"answer":1,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选B。","__sub":"选词填空"},{"id":"yy-18987","module":"yanyu","diff":1,"exam":"省考","prompt":"这些年，二十年只做一件事，市场监管部门在细分领域里做到极致。","options":["深挖","深掘","深耕","深钻"],"answer":2,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选C。","__sub":"片段阅读"},{"id":"yy-18988","module":"yanyu","diff":1,"exam":"国考","prompt":"眼下，手握核心技术专利，环卫工人创新的底气。","options":["更硬","更壮","更强","更足"],"answer":3,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选D。","__sub":"片段阅读"},{"id":"yy-18989","module":"yanyu","diff":1,"exam":"事业编","prompt":"这些年，老厂房变身文创园，设计师让工业遗存______新的活力。","options":["换发","更新","焕新","焕发"],"answer":3,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选D。","__sub":"选词填空"},{"id":"yy-18990","module":"yanyu","diff":1,"exam":"省考","prompt":"近期，汛期将至，文旅部门对辖区地质灾害隐患逐点______。","options":["检察","普查","检查","排查"],"answer":3,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选D。","__sub":"选词填空"},{"id":"yy-18991","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，二十年只做一件事，电力工人在细分领域里做到极致。","options":["深掘","深钻","深挖","深耕"],"answer":3,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选D。","__sub":"片段阅读"},{"id":"yy-18992","module":"yanyu","diff":1,"exam":"教师编","prompt":"开春以来，减税降费政策落地，茶农让企业真切感受到红利。","options":["发放","发射","散发","释放"],"answer":3,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选D。","__sub":"片段阅读"},{"id":"yy-18993","module":"yanyu","diff":3,"exam":"国考","prompt":"岁末年初，汛期将至，手工艺人对辖区地质灾害隐患逐点______。","options":["排查","普查","检查","检察"],"answer":0,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选A。","__sub":"选词填空"},{"id":"yy-18994","module":"yanyu","diff":1,"exam":"国考","prompt":"岁末年初，一二三产融合发展，医护人员推动产业链不断延伸。","options":["延伸","延长","拉长","伸长"],"answer":0,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选A。","__sub":"片段阅读"},{"id":"yy-18995","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，把资源优势变成产业优势，教师下大气力______区域品牌。","options":["打制","锻打","拍打","打造"],"answer":3,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-18996","module":"yanyu","diff":3,"exam":"省考","prompt":"盛夏时节，发展为了人民，渔民把一件件民生实事办到群众心坎上，持续______福祉。","options":["增殖","增添","增加","增进"],"answer":3,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选D。","__sub":"选词填空"},{"id":"yy-18997","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，万丈高楼平地起，执法人员一锤一钎______发展基础。","options":["踩实","填实","砸实","夯实"],"answer":3,"explanation":"「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-18998","module":"yanyu","diff":2,"exam":"省考","prompt":"近年来，汛期将至，护林员对辖区地质灾害隐患逐点______。","options":["检查","普查","检察","排查"],"answer":3,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选D。","__sub":"选词填空"},{"id":"yy-18999","module":"yanyu","diff":3,"exam":"国考","prompt":"这些年，靠山吃山靠水吃水，护林员因地制宜______资源优势。","options":["发扬","发展","发挥","施展"],"answer":2,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选C。","__sub":"选词填空"},{"id":"yy-19000","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，政府、市场、社会同向发力，消防员让各方______成强大合力。","options":["汇合","汇集","聚合","汇聚"],"answer":3,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选D。","__sub":"选词填空"},{"id":"yy-19001","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，一年一度的民生大考结束，老党员向群众______了温暖的答卷。","options":["上缴","递交","呈报","交出"],"answer":3,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。","__sub":"选词填空"},{"id":"yy-19002","module":"yanyu","diff":3,"exam":"医疗编","prompt":"岁末年初，古城修缮不搞大拆大建，果农让千年文脉在街巷间静静流淌。","options":["延续","连接","接通","续接"],"answer":0,"explanation":"「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选A。","__sub":"片段阅读"},{"id":"yy-19003","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，几十年如一日，设计师在平凡岗位上______着为民初心。","options":["守卫","保守","坚守","把守"],"answer":2,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选C。","__sub":"选词填空"},{"id":"yy-19004","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，老旧小区加装电梯、增设车位，乡村医生尽力______居民多样需求。","options":["充盈","满意","充足","满足"],"answer":3,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选D。","__sub":"选词填空"},{"id":"yy-19005","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，一年一度的民生大考结束，网格员向群众______了温暖的答卷。","options":["呈报","交出","上缴","递交"],"answer":1,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选B。","__sub":"选词填空"},{"id":"yy-19006","module":"yanyu","diff":3,"exam":"省考","prompt":"盛夏时节，靠山吃山靠水吃水，志愿者们因地制宜______资源优势。","options":["发挥","施展","发扬","发展"],"answer":0,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选A。","__sub":"选词填空"},{"id":"yy-19007","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，让农产品出村进城，图书管理员多方合力______销售通道。","options":["拓宽","扩宽","开宽","开辟"],"answer":0,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选A。","__sub":"选词填空"},{"id":"yy-19008","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，市场细胞活跃起来，教师让经济肌体活力。","options":["填满","充满","塞满","装满"],"answer":1,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选B。","__sub":"片段阅读"},{"id":"yy-19009","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，市场不是法外之地，调解员以制度______交易秩序。","options":["规范","规正","规定","规整"],"answer":0,"explanation":"「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选A。","__sub":"选词填空"},{"id":"yy-19010","module":"yanyu","diff":3,"exam":"省考","prompt":"近期，春潮拍岸千帆竞，社区规划师感受到创新活力。","options":["流出","涌出","涌动","淌动"],"answer":2,"explanation":"「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选C。","__sub":"片段阅读"},{"id":"yy-19011","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，发展为了人民，环卫工人把一件件民生实事办到群众心坎上，持续______福祉。","options":["增进","增加","增殖","增添"],"answer":0,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选A。","__sub":"选词填空"},{"id":"yy-19012","module":"yanyu","diff":1,"exam":"国考","prompt":"这些年，二十年只做一件事，手工艺人在细分领域里做到极致。","options":["深挖","深钻","深耕","深掘"],"answer":2,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选C。","__sub":"片段阅读"},{"id":"yy-19013","module":"yanyu","diff":3,"exam":"事业编","prompt":"入冬以来，誓师大会上，非遗传承人精神斗志，誓言响彻训练场。","options":["高扬","高昂","高涨","昂扬"],"answer":3,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19014","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，政府、市场、社会同向发力，博物馆讲解员让各方______成强大合力。","options":["汇聚","汇集","汇合","聚合"],"answer":0,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选A。","__sub":"选词填空"},{"id":"yy-19015","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，金融活水精准滴灌，设计师为小微企业______发展动力。","options":["灌输","输入","灌入","注入"],"answer":3,"explanation":"「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选D。","__sub":"选词填空"},{"id":"yy-19016","module":"yanyu","diff":2,"exam":"教师编","prompt":"开春以来，放宽准入激发创业热情，驻村干部让创造活力。","options":["流出","淌出","涌出","涌流"],"answer":3,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选D。","__sub":"片段阅读"},{"id":"yy-19017","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，靠山吃山靠水吃水，非遗传承人因地制宜______资源优势。","options":["施展","发挥","发展","发扬"],"answer":1,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选B。","__sub":"选词填空"},{"id":"yy-19018","module":"yanyu","diff":2,"exam":"医疗编","prompt":"一段时间以来，两岸同胞亲情割不断，治沙工人为青年交流______心灵心桥。","options":["修筑","架起","铺设","垒砌"],"answer":1,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选B。","__sub":"选词填空"},{"id":"yy-19019","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，红色资源是最生动的教材，医护人员让红色血脉代代相传。","options":["赓续","延续","接续","继续"],"answer":0,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19020","module":"yanyu","diff":2,"exam":"医疗编","prompt":"连日来，让监督机制长出牙齿，乡村医生把制度笼子越扎越紧。","options":["健全","修理","修葺","修复"],"answer":0,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选A。","__sub":"片段阅读"},{"id":"yy-19021","module":"yanyu","diff":1,"exam":"教师编","prompt":"一段时间以来，红色资源是最生动的教材，程序员让红色血脉代代相传。","options":["赓续","延续","继续","接续"],"answer":0,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19022","module":"yanyu","diff":2,"exam":"省考","prompt":"连日来，红色资源是最生动的教材，基层干部让红色血脉代代相传。","options":["延续","赓续","继续","接续"],"answer":1,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选B。","__sub":"片段阅读"},{"id":"yy-19023","module":"yanyu","diff":1,"exam":"省考","prompt":"入冬以来，人才是创新的第一资源，社区规划师把发展根基越培越厚。","options":["培土","施肥","厚植","浇灌"],"answer":2,"explanation":"「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选C。","__sub":"片段阅读"},{"id":"yy-19024","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，被动状态必须改变，图书管理员用硬措施______了不利局面。","options":["反转","回转","倒转","扭转"],"answer":3,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选D。","__sub":"选词填空"},{"id":"yy-19025","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，几十年如一日，社区工作者在平凡岗位上______着为民初心。","options":["把守","保守","坚守","守卫"],"answer":2,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选C。","__sub":"选词填空"},{"id":"yy-19026","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，跳出一时一地看发展，网格员着力______开放共赢的新格局。","options":["架造","构建","构作","搭造"],"answer":1,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选B。","__sub":"选词填空"},{"id":"yy-19027","module":"yanyu","diff":2,"exam":"事业编","prompt":"近期，改革到了深水区，环卫工人以钉钉子精神______工作局面。","options":["揭开","翻开","掀开","打开"],"answer":3,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选D。","__sub":"选词填空"},{"id":"yy-19028","module":"yanyu","diff":3,"exam":"教师编","prompt":"初秋时节，民生实事清单公示上墙，电力工人一件一件______承诺。","options":["达成","完成","实现","兑现"],"answer":3,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选D。","__sub":"选词填空"},{"id":"yy-19029","module":"yanyu","diff":3,"exam":"事业编","prompt":"今年以来，几十年如一日，调解员在平凡岗位上______着为民初心。","options":["坚守","把守","保守","守卫"],"answer":0,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选A。","__sub":"选词填空"},{"id":"yy-19030","module":"yanyu","diff":2,"exam":"医疗编","prompt":"岁末年初，跳出一时一地看发展，电力工人着力______开放共赢的新格局。","options":["搭造","构作","构建","架造"],"answer":2,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选C。","__sub":"选词填空"},{"id":"yy-19031","module":"yanyu","diff":2,"exam":"省考","prompt":"近年来，数据孤岛必须连起来，环卫工人下决心______部门间的壁垒。","options":["砸破","打碎","打破","击碎"],"answer":2,"explanation":"「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选C。","__sub":"选词填空"},{"id":"yy-19032","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，誓师大会上，法官精神斗志，誓言响彻训练场。","options":["高扬","昂扬","高涨","高昂"],"answer":1,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选B。","__sub":"片段阅读"},{"id":"yy-19033","module":"yanyu","diff":3,"exam":"国考","prompt":"盛夏时节，小哨兵大作用，环卫工人让基层网格______更大作用。","options":["施展","发挥","发扬","表现"],"answer":1,"explanation":"「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选B。","__sub":"选词填空"},{"id":"yy-19034","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，被动状态必须改变，图书管理员用硬措施______了不利局面。","options":["反转","倒转","回转","扭转"],"answer":3,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选D。","__sub":"选词填空"},{"id":"yy-19035","module":"yanyu","diff":1,"exam":"事业编","prompt":"近期，每一起案件都关乎群众对法治的信仰，消防员用公正裁判______正义。","options":["护卫","防御","保卫","捍卫"],"answer":3,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选D。","__sub":"选词填空"},{"id":"yy-19036","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，在广袤乡野间，调解员用汗水______出乡村振兴的崭新篇章。","options":["描红","书写","誊写","抄写"],"answer":1,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选B。","__sub":"选词填空"},{"id":"yy-19037","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，手握核心技术专利，快递员创新的底气。","options":["更强","更壮","更足","更硬"],"answer":2,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选C。","__sub":"片段阅读"},{"id":"yy-19038","module":"yanyu","diff":1,"exam":"事业编","prompt":"近期，绿水青山就是金山银山，图书管理员代代接力______绿色生态。","options":["看守","守候","守护","守望"],"answer":2,"explanation":"「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选C。","__sub":"选词填空"},{"id":"yy-19039","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，手握核心技术专利，非遗传承人创新的底气。","options":["更足","更壮","更强","更硬"],"answer":0,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选A。","__sub":"片段阅读"},{"id":"yy-19040","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，把消费潜力转化为增长实绩，非遗传承人拿出了实招硬招。","options":["释放","散发","发泄","喷发"],"answer":0,"explanation":"「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选A。","__sub":"片段阅读"},{"id":"yy-19041","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，万丈高楼平地起，社区规划师一锤一钎______发展基础。","options":["夯实","砸实","填实","踩实"],"answer":0,"explanation":"「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-19042","module":"yanyu","diff":3,"exam":"国考","prompt":"连日来，一二三产融合发展，志愿者们推动产业链不断延伸。","options":["延伸","延长","拉长","伸长"],"answer":0,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选A。","__sub":"片段阅读"},{"id":"yy-19043","module":"yanyu","diff":3,"exam":"省考","prompt":"近期，几十年如一日，设计师在平凡岗位上______着为民初心。","options":["坚守","把守","保守","守卫"],"answer":0,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选A。","__sub":"选词填空"},{"id":"yy-19044","module":"yanyu","diff":3,"exam":"事业编","prompt":"今年以来，金杯银杯不如老百姓的口碑，程序员把每件小事都当大事办。","options":["创立","树立","建立","设立"],"answer":1,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选B。","__sub":"片段阅读"},{"id":"yy-19045","module":"yanyu","diff":1,"exam":"事业编","prompt":"初秋时节，汛期将至，消防员对辖区地质灾害隐患逐点______。","options":["检察","检查","排查","普查"],"answer":2,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选C。","__sub":"选词填空"},{"id":"yy-19046","module":"yanyu","diff":3,"exam":"医疗编","prompt":"入冬以来，让监督机制长出牙齿，治沙工人把制度笼子越扎越紧。","options":["健全","修理","修复","修葺"],"answer":0,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选A。","__sub":"片段阅读"},{"id":"yy-19047","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，筑起生态安全屏障，医护人员让青山常在绿水长流。","options":["筑牢","锁牢","砌牢","拴牢"],"answer":0,"explanation":"「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选A。","__sub":"片段阅读"},{"id":"yy-19048","module":"yanyu","diff":2,"exam":"事业编","prompt":"近年来，改革红利持续显现，市场活力不断，科研人员信心更足。","options":["迸发","爆发","突发","暴发"],"answer":0,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选A。","__sub":"片段阅读"},{"id":"yy-19049","module":"yanyu","diff":2,"exam":"国考","prompt":"连日来，跳出一时一地看发展，电力工人着力______开放共赢的新格局。","options":["构建","搭造","构作","架造"],"answer":0,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选A。","__sub":"选词填空"},{"id":"yy-19050","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，一年一度的民生大考结束，执法人员向群众______了温暖的答卷。","options":["交出","呈报","递交","上缴"],"answer":0,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选A。","__sub":"选词填空"},{"id":"yy-19051","module":"yanyu","diff":1,"exam":"国考","prompt":"这些年，把消费潜力转化为增长实绩，医护人员拿出了实招硬招。","options":["释放","发泄","散发","喷发"],"answer":0,"explanation":"「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选A。","__sub":"片段阅读"},{"id":"yy-19052","module":"yanyu","diff":1,"exam":"教师编","prompt":"近期，靠山吃山靠水吃水，农技人员因地制宜______资源优势。","options":["施展","发挥","发展","发扬"],"answer":1,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选B。","__sub":"选词填空"},{"id":"yy-19053","module":"yanyu","diff":2,"exam":"事业编","prompt":"入冬以来，改革红利持续显现，市场活力不断，医护人员信心更足。","options":["爆发","突发","迸发","暴发"],"answer":2,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。","__sub":"片段阅读"},{"id":"yy-19054","module":"yanyu","diff":3,"exam":"省考","prompt":"近年来，脱贫不是终点，电力工人多措并举______脱贫成果。","options":["稳固","加固","凝固","巩固"],"answer":3,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选D。","__sub":"选词填空"},{"id":"yy-19055","module":"yanyu","diff":3,"exam":"事业编","prompt":"岁末年初，面对转型路上的重重难关，电力工人迎难而上，把一个个难关逐一______。","options":["破除","克服","攻克","化解"],"answer":2,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选C。","__sub":"选词填空"},{"id":"yy-19056","module":"yanyu","diff":2,"exam":"医疗编","prompt":"今年以来，市场细胞活跃起来，乡村医生让经济肌体活力。","options":["塞满","充满","填满","装满"],"answer":1,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选B。","__sub":"片段阅读"},{"id":"yy-19057","module":"yanyu","diff":1,"exam":"教师编","prompt":"开春以来，乡情是最深的牵挂，果农以商会为平台______情感纽带。","options":["系牢","捆牢","织牢","绑牢"],"answer":2,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选C。","__sub":"选词填空"},{"id":"yy-19058","module":"yanyu","diff":1,"exam":"国考","prompt":"连日来，几十年如一日，市场监管部门在平凡岗位上______着为民初心。","options":["把守","保守","坚守","守卫"],"answer":2,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选C。","__sub":"选词填空"},{"id":"yy-19059","module":"yanyu","diff":1,"exam":"事业编","prompt":"近年来，每一起案件都关乎群众对法治的信仰，手工艺人用公正裁判______正义。","options":["捍卫","保卫","护卫","防御"],"answer":0,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选A。","__sub":"选词填空"},{"id":"yy-19060","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，金杯银杯不如老百姓的口碑，法官把每件小事都当大事办。","options":["设立","树立","创立","建立"],"answer":1,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选B。","__sub":"片段阅读"},{"id":"yy-19061","module":"yanyu","diff":1,"exam":"省考","prompt":"一段时间以来，二十年只做一件事，护林员在细分领域里做到极致。","options":["深钻","深耕","深挖","深掘"],"answer":1,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选B。","__sub":"片段阅读"},{"id":"yy-19062","module":"yanyu","diff":2,"exam":"医疗编","prompt":"今年以来，景区客流高峰来临，图书管理员全员上岗______游览秩序。","options":["护卫","维护","维持","保护"],"answer":1,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选B。","__sub":"选词填空"},{"id":"yy-19063","module":"yanyu","diff":3,"exam":"省考","prompt":"盛夏时节，誓师大会上，驻村干部精神斗志，誓言响彻训练场。","options":["昂扬","高昂","高扬","高涨"],"answer":0,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19064","module":"yanyu","diff":2,"exam":"医疗编","prompt":"近期，把监督防线扎到最基层，快递员走村入户听民声。","options":["织密","缝密","织厚","织补"],"answer":0,"explanation":"「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选A。","__sub":"片段阅读"},{"id":"yy-19065","module":"yanyu","diff":3,"exam":"事业编","prompt":"近年来，一网通办让数据多跑路，审计人员以流程再造______政务效能。","options":["提升","抬高","提高","拔高"],"answer":0,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选A。","__sub":"选词填空"},{"id":"yy-19066","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，老工业基地涅槃重生，社区工作者加快新旧动能步伐。","options":["转变","转换","改换","变换"],"answer":1,"explanation":"「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选B。","__sub":"片段阅读"},{"id":"yy-19067","module":"yanyu","diff":2,"exam":"事业编","prompt":"初秋时节，向存量要效益，医护人员为产业升级______新空间。","options":["拓开","展开","拓展","开展"],"answer":2,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选C。","__sub":"选词填空"},{"id":"yy-19068","module":"yanyu","diff":2,"exam":"教师编","prompt":"近年来，改革红利持续显现，市场活力不断，基层干部信心更足。","options":["爆发","突发","迸发","暴发"],"answer":2,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。","__sub":"片段阅读"},{"id":"yy-19069","module":"yanyu","diff":2,"exam":"事业编","prompt":"今年以来，营商环境就是生产力，民警让企业成长有沃土。","options":["培植","培养","厚植","培育"],"answer":2,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选C。","__sub":"片段阅读"},{"id":"yy-19070","module":"yanyu","diff":2,"exam":"事业编","prompt":"连日来，安全底线不可逾越，茶农24小时轮班值守。","options":["看守","坚守","镇守","把守"],"answer":1,"explanation":"「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选B。","__sub":"片段阅读"},{"id":"yy-19071","module":"yanyu","diff":2,"exam":"事业编","prompt":"开春以来，夜市灯火点亮街巷，茶农为城市______了烟火活力。","options":["增补","增加","增添","追加"],"answer":2,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选C。","__sub":"选词填空"},{"id":"yy-19072","module":"yanyu","diff":1,"exam":"省考","prompt":"盛夏时节，每个孩子都有闪光点，民警善于______学生潜能。","options":["掘取","开采","挖掘","挖出"],"answer":2,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选C。","__sub":"选词填空"},{"id":"yy-19073","module":"yanyu","diff":2,"exam":"省考","prompt":"岁末年初，齐抓共管不是一句口号，博物馆讲解员推动齐抓共管合力。","options":["成形","成型","形成","成立"],"answer":2,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选C。","__sub":"片段阅读"},{"id":"yy-19074","module":"yanyu","diff":2,"exam":"省考","prompt":"岁末年初，产业发展的根基越牢，抗风险的能力就越强，调解员深谙此理，先把根基打扎实。","options":["铺设","垒砌","夯实","敲打"],"answer":2,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选C。","__sub":"片段阅读"},{"id":"yy-19075","module":"yanyu","diff":2,"exam":"事业编","prompt":"初秋时节，景区客流高峰来临，工程师全员上岗______游览秩序。","options":["维护","保护","维持","护卫"],"answer":0,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选A。","__sub":"选词填空"},{"id":"yy-19076","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，让公共服务覆盖城乡，法官持续______政策体系。","options":["修完","完缮","补完","完善"],"answer":3,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选D。","__sub":"选词填空"},{"id":"yy-19077","module":"yanyu","diff":1,"exam":"事业编","prompt":"开春以来，两岸同胞亲情割不断，乡村医生为青年交流______心灵心桥。","options":["架起","铺设","修筑","垒砌"],"answer":0,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选A。","__sub":"选词填空"},{"id":"yy-19078","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，万丈高楼平地起，青年学子一锤一钎______发展基础。","options":["砸实","填实","夯实","踩实"],"answer":2,"explanation":"「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选C。","__sub":"选词填空"},{"id":"yy-19079","module":"yanyu","diff":1,"exam":"省考","prompt":"初秋时节，人才是创新的第一资源，税务干部把发展根基越培越厚。","options":["培土","厚植","浇灌","施肥"],"answer":1,"explanation":"「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选B。","__sub":"片段阅读"},{"id":"yy-19080","module":"yanyu","diff":1,"exam":"省考","prompt":"初秋时节，每一起案件都关乎群众对法治的信仰，铁路养护工用公正裁判______正义。","options":["保卫","护卫","捍卫","防御"],"answer":2,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选C。","__sub":"选词填空"},{"id":"yy-19081","module":"yanyu","diff":2,"exam":"省考","prompt":"连日来，把监督防线扎到最基层，公交司机走村入户听民声。","options":["织厚","织补","缝密","织密"],"answer":3,"explanation":"「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选D。","__sub":"片段阅读"},{"id":"yy-19082","module":"yanyu","diff":3,"exam":"省考","prompt":"盛夏时节，安全底线不可逾越，渔民24小时轮班值守。","options":["看守","把守","坚守","镇守"],"answer":2,"explanation":"「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选C。","__sub":"片段阅读"},{"id":"yy-19083","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，市场不是法外之地，图书管理员以制度______交易秩序。","options":["规定","规范","规整","规正"],"answer":1,"explanation":"「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选B。","__sub":"选词填空"},{"id":"yy-19084","module":"yanyu","diff":2,"exam":"事业编","prompt":"今年以来，让新业态释放新动能，税务干部在制度创新上先行先试。","options":["点燃","引爆","激发","发动"],"answer":2,"explanation":"「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选C。","__sub":"片段阅读"},{"id":"yy-19085","module":"yanyu","diff":3,"exam":"医疗编","prompt":"眼下，齐抓共管不是一句口号，教师推动齐抓共管合力。","options":["成立","成型","成形","形成"],"answer":3,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19086","module":"yanyu","diff":1,"exam":"国考","prompt":"眼下，被动状态必须改变，税务干部用硬措施______了不利局面。","options":["回转","扭转","反转","倒转"],"answer":1,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选B。","__sub":"选词填空"},{"id":"yy-19087","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，每一起案件都关乎群众对法治的信仰，教师用公正裁判______正义。","options":["保卫","防御","捍卫","护卫"],"answer":2,"explanation":"「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选C。","__sub":"选词填空"},{"id":"yy-19088","module":"yanyu","diff":1,"exam":"省考","prompt":"一段时间以来，绿水青山就是金山银山，教师代代接力______绿色生态。","options":["看守","守候","守望","守护"],"answer":3,"explanation":"「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选D。","__sub":"选词填空"},{"id":"yy-19089","module":"yanyu","diff":3,"exam":"国考","prompt":"这些年，每个孩子都有闪光点，程序员善于______学生潜能。","options":["掘取","挖掘","开采","挖出"],"answer":1,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选B。","__sub":"选词填空"},{"id":"yy-19090","module":"yanyu","diff":3,"exam":"省考","prompt":"盛夏时节，新区建设的宏伟蓝图已经展开，快递员正把一张张蓝图变成施工图。","options":["绘就","修筑","编织","耕耘"],"answer":0,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选A。","__sub":"片段阅读"},{"id":"yy-19091","module":"yanyu","diff":2,"exam":"医疗编","prompt":"开春以来，红色资源是最生动的教材，市场监管部门让红色血脉代代相传。","options":["赓续","延续","接续","继续"],"answer":0,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19092","module":"yanyu","diff":1,"exam":"国考","prompt":"眼下，发展为了人民，工程师把一件件民生实事办到群众心坎上，持续______福祉。","options":["增殖","增加","增进","增添"],"answer":2,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选C。","__sub":"选词填空"},{"id":"yy-19093","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，放宽准入激发创业热情，设计师让创造活力。","options":["涌流","淌出","涌出","流出"],"answer":0,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选A。","__sub":"片段阅读"},{"id":"yy-19094","module":"yanyu","diff":1,"exam":"国考","prompt":"盛夏时节，越是众声喧哗，越需要______共识，基层干部把大家的心拢到一起。","options":["凝聚","凝结","凝固","冻住"],"answer":0,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选A。","__sub":"选词填空"},{"id":"yy-19095","module":"yanyu","diff":2,"exam":"事业编","prompt":"初秋时节，被动状态必须改变，手工艺人用硬措施______了不利局面。","options":["反转","倒转","扭转","回转"],"answer":2,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选C。","__sub":"选词填空"},{"id":"yy-19096","module":"yanyu","diff":2,"exam":"省考","prompt":"眼下，民生实事清单公示上墙，志愿者们一件一件______承诺。","options":["实现","完成","兑现","达成"],"answer":2,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选C。","__sub":"选词填空"},{"id":"yy-19097","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，停车难是城市治理的老大难，消防员用共享思维______了这一难题。","options":["解开","解释","破解","解冻"],"answer":2,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选C。","__sub":"选词填空"},{"id":"yy-19098","module":"yanyu","diff":2,"exam":"事业编","prompt":"近年来，放宽准入激发创业热情，法官让创造活力。","options":["流出","涌流","涌出","淌出"],"answer":1,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选B。","__sub":"片段阅读"},{"id":"yy-19099","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，市场不是法外之地，手工艺人以制度______交易秩序。","options":["规正","规范","规整","规定"],"answer":1,"explanation":"「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选B。","__sub":"选词填空"},{"id":"yy-19100","module":"yanyu","diff":2,"exam":"省考","prompt":"一段时间以来，老旧小区加装电梯、增设车位，教师尽力______居民多样需求。","options":["满足","充足","满意","充盈"],"answer":0,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选A。","__sub":"选词填空"},{"id":"yy-19101","module":"yanyu","diff":1,"exam":"事业编","prompt":"连日来，人才是创新的第一资源，驻村干部把发展根基越培越厚。","options":["施肥","培土","浇灌","厚植"],"answer":3,"explanation":"「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选D。","__sub":"片段阅读"},{"id":"yy-19102","module":"yanyu","diff":2,"exam":"事业编","prompt":"初秋时节，急难险重任务面前，青年学子主动______最重的责任。","options":["挑起","背起","抬起","扛起"],"answer":3,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-19103","module":"yanyu","diff":3,"exam":"省考","prompt":"岁末年初，把家国情怀融入课堂，驻村干部用身边故事打动学生。","options":["施肥","浇灌","培土","厚植"],"answer":3,"explanation":"「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19104","module":"yanyu","diff":1,"exam":"国考","prompt":"连日来，众人的事情由众人商量，老党员把各方______到规划图上。","options":["收拢","凝聚","归拢","聚拢"],"answer":1,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选B。","__sub":"选词填空"},{"id":"yy-19105","module":"yanyu","diff":2,"exam":"医疗编","prompt":"入冬以来，让农产品出村进城，网格员多方合力______销售通道。","options":["扩宽","开宽","开辟","拓宽"],"answer":3,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选D。","__sub":"选词填空"},{"id":"yy-19106","module":"yanyu","diff":2,"exam":"事业编","prompt":"连日来，城乡公共服务仍有落差，图书管理员以实策逐步______差距。","options":["减少","缩小","缩减","减小"],"answer":1,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选B。","__sub":"选词填空"},{"id":"yy-19107","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，把资源优势变成产业优势，基层干部下大气力______区域品牌。","options":["锻打","打制","打造","拍打"],"answer":2,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选C。","__sub":"选词填空"},{"id":"yy-19108","module":"yanyu","diff":1,"exam":"省考","prompt":"眼下，传统村落保护性开发，科研人员既富了口袋，也______了乡愁。","options":["截留","留住","扣留","拘留"],"answer":1,"explanation":"「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选B。","__sub":"选词填空"},{"id":"yy-19109","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，传统村落保护性开发，铁路养护工既富了口袋，也______了乡愁。","options":["留住","扣留","截留","拘留"],"answer":0,"explanation":"「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选A。","__sub":"选词填空"},{"id":"yy-19110","module":"yanyu","diff":2,"exam":"教师编","prompt":"近年来，急难险重任务面前，基层干部主动______最重的责任。","options":["扛起","挑起","背起","抬起"],"answer":0,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-19111","module":"yanyu","diff":1,"exam":"事业编","prompt":"一段时间以来，让监督机制长出牙齿，护林员把制度笼子越扎越紧。","options":["健全","修理","修葺","修复"],"answer":0,"explanation":"「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选A。","__sub":"片段阅读"},{"id":"yy-19112","module":"yanyu","diff":3,"exam":"国考","prompt":"这些年，在广袤乡野间，法官用汗水______出乡村振兴的崭新篇章。","options":["书写","描红","誊写","抄写"],"answer":0,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选A。","__sub":"选词填空"},{"id":"yy-19113","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，绿水青山就是金山银山，图书管理员代代接力______绿色生态。","options":["守望","守护","看守","守候"],"answer":1,"explanation":"「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选B。","__sub":"选词填空"},{"id":"yy-19114","module":"yanyu","diff":1,"exam":"省考","prompt":"连日来，一二三产融合发展，基层干部推动产业链不断延伸。","options":["伸长","延长","拉长","延伸"],"answer":3,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。","__sub":"片段阅读"},{"id":"yy-19115","module":"yanyu","diff":1,"exam":"国考","prompt":"眼下，产业发展的根基越牢，抗风险的能力就越强，茶农深谙此理，先把根基打扎实。","options":["铺设","夯实","敲打","垒砌"],"answer":1,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选B。","__sub":"片段阅读"},{"id":"yy-19116","module":"yanyu","diff":3,"exam":"国考","prompt":"入冬以来，跳出一时一地看发展，基层干部着力______开放共赢的新格局。","options":["构建","搭造","构作","架造"],"answer":0,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选A。","__sub":"选词填空"},{"id":"yy-19117","module":"yanyu","diff":3,"exam":"国考","prompt":"一段时间以来，被动状态必须改变，博物馆讲解员用硬措施______了不利局面。","options":["倒转","反转","回转","扭转"],"answer":3,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选D。","__sub":"选词填空"},{"id":"yy-19118","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，让农产品出村进城，社区工作者多方合力______销售通道。","options":["开辟","开宽","拓宽","扩宽"],"answer":2,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选C。","__sub":"选词填空"},{"id":"yy-19119","module":"yanyu","diff":1,"exam":"事业编","prompt":"开春以来，一次次说到做到，基层干部用行动______了群众的信任。","options":["获得","赢得","博得","换取"],"answer":1,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选B。","__sub":"选词填空"},{"id":"yy-19120","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，两岸同胞亲情割不断，铁路养护工为青年交流______心灵心桥。","options":["垒砌","修筑","架起","铺设"],"answer":2,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选C。","__sub":"选词填空"},{"id":"yy-19121","module":"yanyu","diff":2,"exam":"事业编","prompt":"近期，乡情是最深的牵挂，果农以商会为平台______情感纽带。","options":["系牢","捆牢","绑牢","织牢"],"answer":3,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选D。","__sub":"选词填空"},{"id":"yy-19122","module":"yanyu","diff":3,"exam":"省考","prompt":"这些年，民生实事清单公示上墙，网格员一件一件______承诺。","options":["完成","实现","达成","兑现"],"answer":3,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选D。","__sub":"选词填空"},{"id":"yy-19123","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，众人的事情由众人商量，图书管理员把各方______到规划图上。","options":["收拢","凝聚","聚拢","归拢"],"answer":1,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选B。","__sub":"选词填空"},{"id":"yy-19124","module":"yanyu","diff":3,"exam":"国考","prompt":"近年来，越是众声喧哗，越需要______共识，博物馆讲解员把大家的心拢到一起。","options":["凝结","凝聚","冻住","凝固"],"answer":1,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选B。","__sub":"选词填空"},{"id":"yy-19125","module":"yanyu","diff":1,"exam":"事业编","prompt":"近年来，一年一度的民生大考结束，审计人员向群众______了温暖的答卷。","options":["递交","交出","上缴","呈报"],"answer":1,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选B。","__sub":"选词填空"},{"id":"yy-19126","module":"yanyu","diff":1,"exam":"事业编","prompt":"初秋时节，汛期将至，教师对辖区地质灾害隐患逐点______。","options":["普查","排查","检查","检察"],"answer":1,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选B。","__sub":"选词填空"},{"id":"yy-19127","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，两岸同胞亲情割不断，社区规划师为青年交流______心灵心桥。","options":["修筑","垒砌","架起","铺设"],"answer":2,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选C。","__sub":"选词填空"},{"id":"yy-19128","module":"yanyu","diff":3,"exam":"事业编","prompt":"今年以来，让新业态释放新动能，电力工人在制度创新上先行先试。","options":["引爆","激发","点燃","发动"],"answer":1,"explanation":"「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选B。","__sub":"片段阅读"},{"id":"yy-19129","module":"yanyu","diff":1,"exam":"教师编","prompt":"开春以来，每个孩子都有闪光点，工程师善于______学生潜能。","options":["开采","挖出","挖掘","掘取"],"answer":2,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选C。","__sub":"选词填空"},{"id":"yy-19130","module":"yanyu","diff":2,"exam":"医疗编","prompt":"岁末年初，急难险重任务面前，消防员主动______最重的责任。","options":["扛起","挑起","背起","抬起"],"answer":0,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-19131","module":"yanyu","diff":1,"exam":"国考","prompt":"开春以来，一年一度的民生大考结束，护林员向群众______了温暖的答卷。","options":["上缴","交出","呈报","递交"],"answer":1,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选B。","__sub":"选词填空"},{"id":"yy-19132","module":"yanyu","diff":3,"exam":"事业编","prompt":"今年以来，危难时刻冲得上去，博物馆讲解员的行动______了共产党员的担当。","options":["显露","显摆","暴露","彰显"],"answer":3,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选D。","__sub":"选词填空"},{"id":"yy-19133","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，一二三产融合发展，执法人员推动产业链不断延伸。","options":["延伸","拉长","伸长","延长"],"answer":0,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选A。","__sub":"片段阅读"},{"id":"yy-19134","module":"yanyu","diff":1,"exam":"国考","prompt":"初秋时节，众人的事情由众人商量，护林员把各方______到规划图上。","options":["收拢","归拢","凝聚","聚拢"],"answer":2,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选C。","__sub":"选词填空"},{"id":"yy-19135","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，内生动力从哪里来？快递员把功夫下在创新上。","options":["增大","加强","增添","增强"],"answer":3,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19136","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，把风险挺在前面，铁路养护工织密织牢安全网。","options":["防范","提防","防守","防备"],"answer":0,"explanation":"「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选A。","__sub":"片段阅读"},{"id":"yy-19137","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，政府、市场、社会同向发力，文旅部门让各方______成强大合力。","options":["汇集","汇合","聚合","汇聚"],"answer":3,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选D。","__sub":"选词填空"},{"id":"yy-19138","module":"yanyu","diff":3,"exam":"省考","prompt":"今年以来，纪律规矩挺在前面，乡村医生始终______纪律底线。","options":["看守","遵守","严守","把守"],"answer":2,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选C。","__sub":"选词填空"},{"id":"yy-19139","module":"yanyu","diff":2,"exam":"教师编","prompt":"盛夏时节，景区客流高峰来临，茶农全员上岗______游览秩序。","options":["保护","维持","护卫","维护"],"answer":3,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选D。","__sub":"选词填空"},{"id":"yy-19140","module":"yanyu","diff":3,"exam":"事业编","prompt":"眼下，齐抓共管不是一句口号，税务干部推动齐抓共管合力。","options":["成型","成立","成形","形成"],"answer":3,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19141","module":"yanyu","diff":1,"exam":"事业编","prompt":"一段时间以来，内生动力从哪里来？市场监管部门把功夫下在创新上。","options":["增大","增强","加强","增添"],"answer":1,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选B。","__sub":"片段阅读"},{"id":"yy-19142","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，众人的事情由众人商量，博物馆讲解员把各方______到规划图上。","options":["聚拢","收拢","凝聚","归拢"],"answer":2,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选C。","__sub":"选词填空"},{"id":"yy-19143","module":"yanyu","diff":1,"exam":"教师编","prompt":"这些年，在广袤乡野间，执法人员用汗水______出乡村振兴的崭新篇章。","options":["描红","誊写","抄写","书写"],"answer":3,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选D。","__sub":"选词填空"},{"id":"yy-19144","module":"yanyu","diff":1,"exam":"国考","prompt":"眼下，把资源优势变成产业优势，医护人员下大气力______区域品牌。","options":["打制","拍打","锻打","打造"],"answer":3,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-19145","module":"yanyu","diff":3,"exam":"省考","prompt":"入冬以来，景区客流高峰来临，调解员全员上岗______游览秩序。","options":["保护","维护","维持","护卫"],"answer":1,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选B。","__sub":"选词填空"},{"id":"yy-19146","module":"yanyu","diff":2,"exam":"事业编","prompt":"岁末年初，金融活水精准滴灌，乡村医生为小微企业______发展动力。","options":["灌入","注入","灌输","输入"],"answer":1,"explanation":"「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选B。","__sub":"选词填空"},{"id":"yy-19147","module":"yanyu","diff":3,"exam":"国考","prompt":"这些年，夜市灯火点亮街巷，程序员为城市______了烟火活力。","options":["增补","追加","增添","增加"],"answer":2,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选C。","__sub":"选词填空"},{"id":"yy-19148","module":"yanyu","diff":1,"exam":"事业编","prompt":"初秋时节，让新业态释放新动能，图书管理员在制度创新上先行先试。","options":["发动","激发","点燃","引爆"],"answer":1,"explanation":"「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选B。","__sub":"片段阅读"},{"id":"yy-19149","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，几十年如一日，社区工作者在平凡岗位上______着为民初心。","options":["守卫","把守","保守","坚守"],"answer":3,"explanation":"「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选D。","__sub":"选词填空"},{"id":"yy-19150","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，被动状态必须改变，老党员用硬措施______了不利局面。","options":["扭转","倒转","反转","回转"],"answer":0,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选A。","__sub":"选词填空"},{"id":"yy-19151","module":"yanyu","diff":3,"exam":"省考","prompt":"近期，越是爬坡过坎，越要______必胜信心，电力工人一步一个脚印向前走。","options":["坚强","坚定","坚持不懈","坚决"],"answer":1,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选B。","__sub":"选词填空"},{"id":"yy-19152","module":"yanyu","diff":3,"exam":"省考","prompt":"这些年，老工业基地涅槃重生，设计师加快新旧动能步伐。","options":["变换","改换","转换","转变"],"answer":2,"explanation":"「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选C。","__sub":"片段阅读"},{"id":"yy-19153","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，急难险重任务面前，非遗传承人主动______最重的责任。","options":["扛起","背起","抬起","挑起"],"answer":0,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-19154","module":"yanyu","diff":1,"exam":"国考","prompt":"岁末年初，内生动力从哪里来？文旅部门把功夫下在创新上。","options":["加强","增大","增强","增添"],"answer":2,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选C。","__sub":"片段阅读"},{"id":"yy-19155","module":"yanyu","diff":3,"exam":"省考","prompt":"连日来，安全底线不可逾越，老党员24小时轮班值守。","options":["看守","坚守","镇守","把守"],"answer":1,"explanation":"「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选B。","__sub":"片段阅读"},{"id":"yy-19156","module":"yanyu","diff":1,"exam":"省考","prompt":"岁末年初，让公共服务覆盖城乡，治沙工人持续______政策体系。","options":["修完","完善","补完","完缮"],"answer":1,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选B。","__sub":"选词填空"},{"id":"yy-19157","module":"yanyu","diff":2,"exam":"省考","prompt":"近年来，齐抓共管不是一句口号，社区规划师推动齐抓共管合力。","options":["成型","成立","成形","形成"],"answer":3,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19158","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，营商环境就是生产力，治沙工人让企业成长有沃土。","options":["厚植","培植","培育","培养"],"answer":0,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19159","module":"yanyu","diff":1,"exam":"事业编","prompt":"入冬以来，订单排到明年，青年学子发展的信心。","options":["倍加","倍受","倍增","加倍"],"answer":2,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选C。","__sub":"片段阅读"},{"id":"yy-19160","module":"yanyu","diff":2,"exam":"国考","prompt":"连日来，危难时刻冲得上去，茶农的行动______了共产党员的担当。","options":["显摆","显露","彰显","暴露"],"answer":2,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选C。","__sub":"选词填空"},{"id":"yy-19161","module":"yanyu","diff":3,"exam":"事业编","prompt":"今年以来，红色资源是最生动的教材，执法人员让红色血脉代代相传。","options":["赓续","继续","延续","接续"],"answer":0,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19162","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，一揽子政策精准落地，农技人员着力______市场信心。","options":["提振","提起","鼓动","振作"],"answer":0,"explanation":"「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选A。","__sub":"选词填空"},{"id":"yy-19163","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，乡情是最深的牵挂，社区工作者以商会为平台______情感纽带。","options":["绑牢","捆牢","系牢","织牢"],"answer":3,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选D。","__sub":"选词填空"},{"id":"yy-19164","module":"yanyu","diff":1,"exam":"事业编","prompt":"近年来，每个孩子都有闪光点，图书管理员善于______学生潜能。","options":["挖掘","挖出","掘取","开采"],"answer":0,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选A。","__sub":"选词填空"},{"id":"yy-19165","module":"yanyu","diff":3,"exam":"事业编","prompt":"一段时间以来，一网通办让数据多跑路，图书管理员以流程再造______政务效能。","options":["提高","提升","拔高","抬高"],"answer":1,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选B。","__sub":"选词填空"},{"id":"yy-19166","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，老厂房变身文创园，护林员让工业遗存______新的活力。","options":["焕发","换发","焕新","更新"],"answer":0,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选A。","__sub":"选词填空"},{"id":"yy-19167","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，把消费潜力转化为增长实绩，网格员拿出了实招硬招。","options":["发泄","释放","喷发","散发"],"answer":1,"explanation":"「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选B。","__sub":"片段阅读"},{"id":"yy-19168","module":"yanyu","diff":1,"exam":"事业编","prompt":"眼下，减税降费政策落地，民警让企业真切感受到红利。","options":["发射","散发","释放","发放"],"answer":2,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选C。","__sub":"片段阅读"},{"id":"yy-19169","module":"yanyu","diff":3,"exam":"国考","prompt":"近年来，一次次说到做到，图书管理员用行动______了群众的信任。","options":["获得","博得","赢得","换取"],"answer":2,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选C。","__sub":"选词填空"},{"id":"yy-19170","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，政府、市场、社会同向发力，教师让各方______成强大合力。","options":["汇集","汇合","汇聚","聚合"],"answer":2,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选C。","__sub":"选词填空"},{"id":"yy-19171","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，脱贫不是终点，非遗传承人多措并举______脱贫成果。","options":["巩固","稳固","凝固","加固"],"answer":0,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。","__sub":"选词填空"},{"id":"yy-19172","module":"yanyu","diff":1,"exam":"省考","prompt":"盛夏时节，发展为了人民，手工艺人把一件件民生实事办到群众心坎上，持续______福祉。","options":["增殖","增加","增添","增进"],"answer":3,"explanation":"「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选D。","__sub":"选词填空"},{"id":"yy-19173","module":"yanyu","diff":1,"exam":"国考","prompt":"初秋时节，二十年只做一件事，手工艺人在细分领域里做到极致。","options":["深掘","深钻","深耕","深挖"],"answer":2,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选C。","__sub":"片段阅读"},{"id":"yy-19174","module":"yanyu","diff":1,"exam":"事业编","prompt":"一段时间以来，面对转型路上的重重难关，茶农迎难而上，把一个个难关逐一______。","options":["克服","攻克","破除","化解"],"answer":1,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选B。","__sub":"选词填空"},{"id":"yy-19175","module":"yanyu","diff":1,"exam":"国考","prompt":"初秋时节，誓师大会上，手工艺人精神斗志，誓言响彻训练场。","options":["昂扬","高涨","高昂","高扬"],"answer":0,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19176","module":"yanyu","diff":3,"exam":"国考","prompt":"近年来，夜市灯火点亮街巷，非遗传承人为城市______了烟火活力。","options":["增补","追加","增添","增加"],"answer":2,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选C。","__sub":"选词填空"},{"id":"yy-19177","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，一二三产融合发展，青年学子推动产业链不断延伸。","options":["延长","拉长","伸长","延伸"],"answer":3,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。","__sub":"片段阅读"},{"id":"yy-19178","module":"yanyu","diff":2,"exam":"事业编","prompt":"近期，脱贫不是终点，文旅部门多措并举______脱贫成果。","options":["巩固","凝固","稳固","加固"],"answer":0,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。","__sub":"选词填空"},{"id":"yy-19179","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，两岸同胞亲情割不断，公交司机为青年交流______心灵心桥。","options":["垒砌","修筑","架起","铺设"],"answer":2,"explanation":"「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选C。","__sub":"选词填空"},{"id":"yy-19180","module":"yanyu","diff":1,"exam":"事业编","prompt":"今年以来，把消费潜力转化为增长实绩，志愿者们拿出了实招硬招。","options":["发泄","喷发","散发","释放"],"answer":3,"explanation":"「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选D。","__sub":"片段阅读"},{"id":"yy-19181","module":"yanyu","diff":3,"exam":"省考","prompt":"岁末年初，城乡公共服务仍有落差，执法人员以实策逐步______差距。","options":["缩小","缩减","减小","减少"],"answer":0,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选A。","__sub":"选词填空"},{"id":"yy-19182","module":"yanyu","diff":1,"exam":"事业编","prompt":"连日来，手握核心技术专利，志愿者们创新的底气。","options":["更足","更硬","更强","更壮"],"answer":0,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选A。","__sub":"片段阅读"},{"id":"yy-19183","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，金杯银杯不如老百姓的口碑，青年学子把每件小事都当大事办。","options":["设立","创立","树立","建立"],"answer":2,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选C。","__sub":"片段阅读"},{"id":"yy-19184","module":"yanyu","diff":3,"exam":"国考","prompt":"眼下，向存量要效益，铁路养护工为产业升级______新空间。","options":["开展","展开","拓展","拓开"],"answer":2,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选C。","__sub":"选词填空"},{"id":"yy-19185","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，急难险重任务面前，博物馆讲解员主动______最重的责任。","options":["抬起","扛起","挑起","背起"],"answer":1,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选B。","__sub":"选词填空"},{"id":"yy-19186","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，一年一度的民生大考结束，护林员向群众______了温暖的答卷。","options":["交出","递交","呈报","上缴"],"answer":0,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选A。","__sub":"选词填空"},{"id":"yy-19187","module":"yanyu","diff":3,"exam":"国考","prompt":"一段时间以来，夜市灯火点亮街巷，老党员为城市______了烟火活力。","options":["增补","增加","增添","追加"],"answer":2,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选C。","__sub":"选词填空"},{"id":"yy-19188","module":"yanyu","diff":1,"exam":"国考","prompt":"这些年，改革红利持续显现，市场活力不断，程序员信心更足。","options":["爆发","暴发","迸发","突发"],"answer":2,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。","__sub":"片段阅读"},{"id":"yy-19189","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，让要素流动更顺畅，就要______体制机制的藩篱。","options":["拆除","铲平","捣毁","破除"],"answer":3,"explanation":"「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选D。","__sub":"选词填空"},{"id":"yy-19190","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，齐抓共管不是一句口号，治沙工人推动齐抓共管合力。","options":["形成","成立","成型","成形"],"answer":0,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19191","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，筑起生态安全屏障，护林员让青山常在绿水长流。","options":["砌牢","锁牢","拴牢","筑牢"],"answer":3,"explanation":"「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选D。","__sub":"片段阅读"},{"id":"yy-19192","module":"yanyu","diff":3,"exam":"省考","prompt":"一段时间以来，跳出一时一地看发展，志愿者们着力______开放共赢的新格局。","options":["构作","构建","架造","搭造"],"answer":1,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选B。","__sub":"选词填空"},{"id":"yy-19193","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，停车难是城市治理的老大难，社区规划师用共享思维______了这一难题。","options":["解开","破解","解冻","解释"],"answer":1,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选B。","__sub":"选词填空"},{"id":"yy-19194","module":"yanyu","diff":2,"exam":"国考","prompt":"一段时间以来，一揽子政策精准落地，乡村医生着力______市场信心。","options":["提振","提起","鼓动","振作"],"answer":0,"explanation":"「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选A。","__sub":"选词填空"},{"id":"yy-19195","module":"yanyu","diff":1,"exam":"国考","prompt":"岁末年初，民生实事清单公示上墙，铁路养护工一件一件______承诺。","options":["完成","达成","实现","兑现"],"answer":3,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选D。","__sub":"选词填空"},{"id":"yy-19196","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，越是爬坡过坎，越要______必胜信心，消防员一步一个脚印向前走。","options":["坚定","坚强","坚持不懈","坚决"],"answer":0,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选A。","__sub":"选词填空"},{"id":"yy-19197","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，邻里纠纷无小事，老党员用真心______一件件矛盾。","options":["消融","瓦解","化解","解开"],"answer":2,"explanation":"「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选C。","__sub":"选词填空"},{"id":"yy-19198","module":"yanyu","diff":2,"exam":"事业编","prompt":"初秋时节，越是爬坡过坎，越要______必胜信心，快递员一步一个脚印向前走。","options":["坚强","坚决","坚持不懈","坚定"],"answer":3,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选D。","__sub":"选词填空"},{"id":"yy-19199","module":"yanyu","diff":3,"exam":"国考","prompt":"初秋时节，景区客流高峰来临，志愿者们全员上岗______游览秩序。","options":["维持","护卫","保护","维护"],"answer":3,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选D。","__sub":"选词填空"},{"id":"yy-19200","module":"yanyu","diff":3,"exam":"国考","prompt":"近期，一次次说到做到，基层干部用行动______了群众的信任。","options":["换取","获得","博得","赢得"],"answer":3,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选D。","__sub":"选词填空"},{"id":"yy-19201","module":"yanyu","diff":1,"exam":"国考","prompt":"入冬以来，民生实事清单公示上墙，广大建设者一件一件______承诺。","options":["达成","兑现","完成","实现"],"answer":1,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选B。","__sub":"选词填空"},{"id":"yy-19202","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，订单排到明年，设计师发展的信心。","options":["倍受","加倍","倍加","倍增"],"answer":3,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19203","module":"yanyu","diff":3,"exam":"国考","prompt":"初秋时节，二十年只做一件事，基层干部在细分领域里做到极致。","options":["深钻","深挖","深耕","深掘"],"answer":2,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选C。","__sub":"片段阅读"},{"id":"yy-19204","module":"yanyu","diff":2,"exam":"省考","prompt":"近年来，一网通办让数据多跑路，图书管理员以流程再造______政务效能。","options":["提升","拔高","抬高","提高"],"answer":0,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选A。","__sub":"选词填空"},{"id":"yy-19205","module":"yanyu","diff":3,"exam":"省考","prompt":"入冬以来，二十年只做一件事，社区工作者在细分领域里做到极致。","options":["深掘","深挖","深耕","深钻"],"answer":2,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选C。","__sub":"片段阅读"},{"id":"yy-19206","module":"yanyu","diff":1,"exam":"事业编","prompt":"一段时间以来，政府、市场、社会同向发力，青年学子让各方______成强大合力。","options":["汇聚","汇合","汇集","聚合"],"answer":0,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选A。","__sub":"选词填空"},{"id":"yy-19207","module":"yanyu","diff":2,"exam":"事业编","prompt":"盛夏时节，内生动力从哪里来？执法人员把功夫下在创新上。","options":["加强","增添","增大","增强"],"answer":3,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19208","module":"yanyu","diff":1,"exam":"国考","prompt":"这些年，产业发展的根基越牢，抗风险的能力就越强，社区规划师深谙此理，先把根基打扎实。","options":["垒砌","夯实","敲打","铺设"],"answer":1,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选B。","__sub":"片段阅读"},{"id":"yy-19209","module":"yanyu","diff":1,"exam":"医疗编","prompt":"初秋时节，誓师大会上，非遗传承人精神斗志，誓言响彻训练场。","options":["高昂","昂扬","高涨","高扬"],"answer":1,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选B。","__sub":"片段阅读"},{"id":"yy-19210","module":"yanyu","diff":2,"exam":"省考","prompt":"一段时间以来，越是众声喧哗，越需要______共识，非遗传承人把大家的心拢到一起。","options":["冻住","凝聚","凝固","凝结"],"answer":1,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选B。","__sub":"选词填空"},{"id":"yy-19211","module":"yanyu","diff":2,"exam":"事业编","prompt":"开春以来，被动状态必须改变，铁路养护工用硬措施______了不利局面。","options":["倒转","扭转","回转","反转"],"answer":1,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选B。","__sub":"选词填空"},{"id":"yy-19212","module":"yanyu","diff":2,"exam":"教师编","prompt":"岁末年初，众人的事情由众人商量，审计人员把各方______到规划图上。","options":["收拢","归拢","凝聚","聚拢"],"answer":2,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选C。","__sub":"选词填空"},{"id":"yy-19213","module":"yanyu","diff":1,"exam":"国考","prompt":"眼下，让农产品出村进城，法官多方合力______销售通道。","options":["开辟","拓宽","开宽","扩宽"],"answer":1,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选B。","__sub":"选词填空"},{"id":"yy-19214","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，小哨兵大作用，非遗传承人让基层网格______更大作用。","options":["表现","发扬","施展","发挥"],"answer":3,"explanation":"「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选D。","__sub":"选词填空"},{"id":"yy-19215","module":"yanyu","diff":1,"exam":"国考","prompt":"入冬以来，春潮拍岸千帆竞，医护人员感受到创新活力。","options":["流出","涌出","涌动","淌动"],"answer":2,"explanation":"「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选C。","__sub":"片段阅读"},{"id":"yy-19216","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，从受理到反馈全流程留痕，护林员以数字化手段______管理闭环。","options":["圈画","构画","构建","搭圈"],"answer":2,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选C。","__sub":"选词填空"},{"id":"yy-19217","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，让公共服务覆盖城乡，设计师持续______政策体系。","options":["完缮","修完","补完","完善"],"answer":3,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选D。","__sub":"选词填空"},{"id":"yy-19218","module":"yanyu","diff":2,"exam":"省考","prompt":"眼下，停车难是城市治理的老大难，设计师用共享思维______了这一难题。","options":["解开","解释","解冻","破解"],"answer":3,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选D。","__sub":"选词填空"},{"id":"yy-19219","module":"yanyu","diff":1,"exam":"省考","prompt":"初秋时节，城乡公共服务仍有落差，教师以实策逐步______差距。","options":["缩减","缩小","减少","减小"],"answer":1,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选B。","__sub":"选词填空"},{"id":"yy-19220","module":"yanyu","diff":1,"exam":"省考","prompt":"眼下，改革到了深水区，非遗传承人以钉钉子精神______工作局面。","options":["翻开","揭开","掀开","打开"],"answer":3,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选D。","__sub":"选词填空"},{"id":"yy-19221","module":"yanyu","diff":2,"exam":"省考","prompt":"入冬以来，被动状态必须改变，社区工作者用硬措施______了不利局面。","options":["倒转","反转","回转","扭转"],"answer":3,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选D。","__sub":"选词填空"},{"id":"yy-19222","module":"yanyu","diff":3,"exam":"国考","prompt":"岁末年初，每个孩子都有闪光点，环卫工人善于______学生潜能。","options":["开采","掘取","挖出","挖掘"],"answer":3,"explanation":"「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。","__sub":"选词填空"},{"id":"yy-19223","module":"yanyu","diff":1,"exam":"事业编","prompt":"近期，绿水青山就是金山银山，手工艺人代代接力______绿色生态。","options":["守候","守望","守护","看守"],"answer":2,"explanation":"「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选C。","__sub":"选词填空"},{"id":"yy-19224","module":"yanyu","diff":1,"exam":"国考","prompt":"盛夏时节，二十年只做一件事，果农在细分领域里做到极致。","options":["深掘","深挖","深钻","深耕"],"answer":3,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选D。","__sub":"片段阅读"},{"id":"yy-19225","module":"yanyu","diff":2,"exam":"医疗编","prompt":"一段时间以来，汛期将至，文旅部门对辖区地质灾害隐患逐点______。","options":["检查","排查","普查","检察"],"answer":1,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选B。","__sub":"选词填空"},{"id":"yy-19226","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，乡情是最深的牵挂，铁路养护工以商会为平台______情感纽带。","options":["系牢","捆牢","绑牢","织牢"],"answer":3,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选D。","__sub":"选词填空"},{"id":"yy-19227","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，改革到了深水区，教师以钉钉子精神______工作局面。","options":["翻开","揭开","打开","掀开"],"answer":2,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选C。","__sub":"选词填空"},{"id":"yy-19228","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，脱贫不是终点，治沙工人多措并举______脱贫成果。","options":["加固","凝固","稳固","巩固"],"answer":3,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选D。","__sub":"选词填空"},{"id":"yy-19229","module":"yanyu","diff":3,"exam":"省考","prompt":"今年以来，改革到了深水区，消防员以钉钉子精神______工作局面。","options":["掀开","揭开","翻开","打开"],"answer":3,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选D。","__sub":"选词填空"},{"id":"yy-19230","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，红色资源是最生动的教材，乡村医生让红色血脉代代相传。","options":["赓续","继续","接续","延续"],"answer":0,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19231","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，让农产品出村进城，环卫工人多方合力______销售通道。","options":["拓宽","开宽","开辟","扩宽"],"answer":0,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选A。","__sub":"选词填空"},{"id":"yy-19232","module":"yanyu","diff":2,"exam":"国考","prompt":"连日来，从受理到反馈全流程留痕，调解员以数字化手段______管理闭环。","options":["构建","搭圈","构画","圈画"],"answer":0,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选A。","__sub":"选词填空"},{"id":"yy-19233","module":"yanyu","diff":3,"exam":"事业编","prompt":"连日来，在广袤乡野间，果农用汗水______出乡村振兴的崭新篇章。","options":["描红","抄写","誊写","书写"],"answer":3,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选D。","__sub":"选词填空"},{"id":"yy-19234","module":"yanyu","diff":1,"exam":"事业编","prompt":"这些年，金融活水精准滴灌，图书管理员为小微企业______发展动力。","options":["灌输","注入","灌入","输入"],"answer":1,"explanation":"「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选B。","__sub":"选词填空"},{"id":"yy-19235","module":"yanyu","diff":1,"exam":"省考","prompt":"一段时间以来，纪律规矩挺在前面，社区工作者始终______纪律底线。","options":["遵守","看守","严守","把守"],"answer":2,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选C。","__sub":"选词填空"},{"id":"yy-19236","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，齐抓共管不是一句口号，调解员推动齐抓共管合力。","options":["成形","成型","形成","成立"],"answer":2,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选C。","__sub":"片段阅读"},{"id":"yy-19237","module":"yanyu","diff":3,"exam":"国考","prompt":"这些年，绿水青山就是金山银山，老党员代代接力______绿色生态。","options":["守护","守望","看守","守候"],"answer":0,"explanation":"「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选A。","__sub":"选词填空"},{"id":"yy-19238","module":"yanyu","diff":1,"exam":"国考","prompt":"入冬以来，卡脖子技术亟待攻坚，社区规划师集中力量______一个个瓶颈。","options":["撞破","捅破","突破","冲破"],"answer":2,"explanation":"「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选C。","__sub":"选词填空"},{"id":"yy-19239","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，改革红利持续显现，市场活力不断，程序员信心更足。","options":["迸发","突发","爆发","暴发"],"answer":0,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选A。","__sub":"片段阅读"},{"id":"yy-19240","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，邻里纠纷无小事，农技人员用真心______一件件矛盾。","options":["消融","瓦解","化解","解开"],"answer":2,"explanation":"「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选C。","__sub":"选词填空"},{"id":"yy-19241","module":"yanyu","diff":2,"exam":"事业编","prompt":"近期，改革红利持续显现，市场活力不断，果农信心更足。","options":["暴发","爆发","迸发","突发"],"answer":2,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。","__sub":"片段阅读"},{"id":"yy-19242","module":"yanyu","diff":1,"exam":"教师编","prompt":"入冬以来，被动状态必须改变，青年学子用硬措施______了不利局面。","options":["反转","回转","倒转","扭转"],"answer":3,"explanation":"「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选D。","__sub":"选词填空"},{"id":"yy-19243","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，内生动力从哪里来？农技人员把功夫下在创新上。","options":["增强","增大","加强","增添"],"answer":0,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19244","module":"yanyu","diff":2,"exam":"教师编","prompt":"今年以来，面对转型路上的重重难关，快递员迎难而上，把一个个难关逐一______。","options":["克服","化解","攻克","破除"],"answer":2,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选C。","__sub":"选词填空"},{"id":"yy-19245","module":"yanyu","diff":3,"exam":"教师编","prompt":"盛夏时节，让农产品出村进城，图书管理员多方合力______销售通道。","options":["开宽","开辟","拓宽","扩宽"],"answer":2,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选C。","__sub":"选词填空"},{"id":"yy-19246","module":"yanyu","diff":2,"exam":"事业编","prompt":"一段时间以来，誓师大会上，铁路养护工精神斗志，誓言响彻训练场。","options":["高扬","高昂","高涨","昂扬"],"answer":3,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19247","module":"yanyu","diff":1,"exam":"省考","prompt":"连日来，民生实事清单公示上墙，非遗传承人一件一件______承诺。","options":["达成","实现","完成","兑现"],"answer":3,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选D。","__sub":"选词填空"},{"id":"yy-19248","module":"yanyu","diff":1,"exam":"教师编","prompt":"岁末年初，老旧小区加装电梯、增设车位，科研人员尽力______居民多样需求。","options":["充足","充盈","满足","满意"],"answer":2,"explanation":"「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选C。","__sub":"选词填空"},{"id":"yy-19249","module":"yanyu","diff":2,"exam":"事业编","prompt":"岁末年初，市场不是法外之地，茶农以制度______交易秩序。","options":["规正","规定","规整","规范"],"answer":3,"explanation":"「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选D。","__sub":"选词填空"},{"id":"yy-19250","module":"yanyu","diff":1,"exam":"省考","prompt":"初秋时节，绿水青山就是金山银山，审计人员代代接力______绿色生态。","options":["看守","守候","守望","守护"],"answer":3,"explanation":"「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选D。","__sub":"选词填空"},{"id":"yy-19251","module":"yanyu","diff":1,"exam":"教师编","prompt":"岁末年初，改革到了深水区，广大建设者以钉钉子精神______工作局面。","options":["打开","揭开","翻开","掀开"],"answer":0,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选A。","__sub":"选词填空"},{"id":"yy-19252","module":"yanyu","diff":1,"exam":"省考","prompt":"近期，危难时刻冲得上去，电力工人的行动______了共产党员的担当。","options":["显摆","暴露","显露","彰显"],"answer":3,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选D。","__sub":"选词填空"},{"id":"yy-19253","module":"yanyu","diff":3,"exam":"省考","prompt":"初秋时节，金融活水精准滴灌，科研人员为小微企业______发展动力。","options":["灌输","灌入","注入","输入"],"answer":2,"explanation":"「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选C。","__sub":"选词填空"},{"id":"yy-19254","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，新区建设的宏伟蓝图已经展开，社区工作者正把一张张蓝图变成施工图。","options":["耕耘","绘就","编织","修筑"],"answer":1,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选B。","__sub":"片段阅读"},{"id":"yy-19255","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，古城修缮不搞大拆大建，教师让千年文脉在街巷间静静流淌。","options":["续接","连接","接通","延续"],"answer":3,"explanation":"「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选D。","__sub":"片段阅读"},{"id":"yy-19256","module":"yanyu","diff":1,"exam":"医疗编","prompt":"岁末年初，越是众声喧哗，越需要______共识，教师把大家的心拢到一起。","options":["冻住","凝固","凝结","凝聚"],"answer":3,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选D。","__sub":"选词填空"},{"id":"yy-19257","module":"yanyu","diff":1,"exam":"事业编","prompt":"初秋时节，政府、市场、社会同向发力，网格员让各方______成强大合力。","options":["汇聚","汇集","聚合","汇合"],"answer":0,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选A。","__sub":"选词填空"},{"id":"yy-19258","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，市场不是法外之地，文旅部门以制度______交易秩序。","options":["规正","规范","规整","规定"],"answer":1,"explanation":"「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选B。","__sub":"选词填空"},{"id":"yy-19259","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，红色资源是最生动的教材，税务干部让红色血脉代代相传。","options":["接续","赓续","继续","延续"],"answer":1,"explanation":"「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选B。","__sub":"片段阅读"},{"id":"yy-19260","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，面对转型路上的重重难关，文旅部门迎难而上，把一个个难关逐一______。","options":["攻克","破除","化解","克服"],"answer":0,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选A。","__sub":"选词填空"},{"id":"yy-19261","module":"yanyu","diff":3,"exam":"事业编","prompt":"入冬以来，一次次说到做到，志愿者们用行动______了群众的信任。","options":["博得","获得","赢得","换取"],"answer":2,"explanation":"「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选C。","__sub":"选词填空"},{"id":"yy-19262","module":"yanyu","diff":1,"exam":"教师编","prompt":"一段时间以来，传统村落保护性开发，税务干部既富了口袋，也______了乡愁。","options":["扣留","截留","留住","拘留"],"answer":2,"explanation":"「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选C。","__sub":"选词填空"},{"id":"yy-19263","module":"yanyu","diff":2,"exam":"省考","prompt":"近年来，众人的事情由众人商量，教师把各方______到规划图上。","options":["收拢","凝聚","聚拢","归拢"],"answer":1,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选B。","__sub":"选词填空"},{"id":"yy-19264","module":"yanyu","diff":2,"exam":"医疗编","prompt":"近期，越是众声喧哗，越需要______共识，法官把大家的心拢到一起。","options":["凝固","凝结","冻住","凝聚"],"answer":3,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选D。","__sub":"选词填空"},{"id":"yy-19265","module":"yanyu","diff":2,"exam":"省考","prompt":"岁末年初，齐抓共管不是一句口号，程序员推动齐抓共管合力。","options":["成型","成立","成形","形成"],"answer":3,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19266","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，纪律规矩挺在前面，快递员始终______纪律底线。","options":["严守","遵守","看守","把守"],"answer":0,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选A。","__sub":"选词填空"},{"id":"yy-19267","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，汛期将至，渔民对辖区地质灾害隐患逐点______。","options":["检查","普查","检察","排查"],"answer":3,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选D。","__sub":"选词填空"},{"id":"yy-19268","module":"yanyu","diff":3,"exam":"省考","prompt":"今年以来，一揽子政策精准落地，渔民着力______市场信心。","options":["提起","提振","鼓动","振作"],"answer":1,"explanation":"「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选B。","__sub":"选词填空"},{"id":"yy-19269","module":"yanyu","diff":3,"exam":"国考","prompt":"盛夏时节，内生动力从哪里来？电力工人把功夫下在创新上。","options":["增大","加强","增强","增添"],"answer":2,"explanation":"「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选C。","__sub":"片段阅读"},{"id":"yy-19270","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，把监督防线扎到最基层，设计师走村入户听民声。","options":["织补","织厚","织密","缝密"],"answer":2,"explanation":"「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选C。","__sub":"片段阅读"},{"id":"yy-19271","module":"yanyu","diff":1,"exam":"国考","prompt":"连日来，春潮拍岸千帆竞，社区规划师感受到创新活力。","options":["涌动","淌动","涌出","流出"],"answer":0,"explanation":"「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选A。","__sub":"片段阅读"},{"id":"yy-19272","module":"yanyu","diff":2,"exam":"省考","prompt":"眼下，古城修缮不搞大拆大建，手工艺人让千年文脉在街巷间静静流淌。","options":["连接","延续","接通","续接"],"answer":1,"explanation":"「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选B。","__sub":"片段阅读"},{"id":"yy-19273","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，危难时刻冲得上去，法官的行动______了共产党员的担当。","options":["彰显","暴露","显露","显摆"],"answer":0,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选A。","__sub":"选词填空"},{"id":"yy-19274","module":"yanyu","diff":3,"exam":"医疗编","prompt":"盛夏时节，古城修缮不搞大拆大建，驻村干部让千年文脉在街巷间静静流淌。","options":["接通","连接","续接","延续"],"answer":3,"explanation":"「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选D。","__sub":"片段阅读"},{"id":"yy-19275","module":"yanyu","diff":3,"exam":"省考","prompt":"今年以来，人才是创新的第一资源，社区规划师把发展根基越培越厚。","options":["浇灌","厚植","施肥","培土"],"answer":1,"explanation":"「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选B。","__sub":"片段阅读"},{"id":"yy-19276","module":"yanyu","diff":1,"exam":"省考","prompt":"今年以来，二十年只做一件事，消防员在细分领域里做到极致。","options":["深挖","深掘","深耕","深钻"],"answer":2,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选C。","__sub":"片段阅读"},{"id":"yy-19277","module":"yanyu","diff":1,"exam":"事业编","prompt":"连日来，小哨兵大作用，科研人员让基层网格______更大作用。","options":["表现","施展","发扬","发挥"],"answer":3,"explanation":"「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选D。","__sub":"选词填空"},{"id":"yy-19278","module":"yanyu","diff":1,"exam":"事业编","prompt":"今年以来，夜市灯火点亮街巷，茶农为城市______了烟火活力。","options":["增补","追加","增加","增添"],"answer":3,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选D。","__sub":"选词填空"},{"id":"yy-19279","module":"yanyu","diff":2,"exam":"医疗编","prompt":"一段时间以来，景区客流高峰来临，民警全员上岗______游览秩序。","options":["维护","保护","护卫","维持"],"answer":0,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选A。","__sub":"选词填空"},{"id":"yy-19280","module":"yanyu","diff":1,"exam":"国考","prompt":"初秋时节，誓师大会上，法官精神斗志，誓言响彻训练场。","options":["高昂","高涨","昂扬","高扬"],"answer":2,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选C。","__sub":"片段阅读"},{"id":"yy-19281","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，减税降费政策落地，科研人员让企业真切感受到红利。","options":["发放","发射","释放","散发"],"answer":2,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选C。","__sub":"片段阅读"},{"id":"yy-19282","module":"yanyu","diff":2,"exam":"医疗编","prompt":"这些年，把家国情怀融入课堂，非遗传承人用身边故事打动学生。","options":["培土","浇灌","施肥","厚植"],"answer":3,"explanation":"「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19283","module":"yanyu","diff":3,"exam":"省考","prompt":"盛夏时节，二十年只做一件事，社区工作者在细分领域里做到极致。","options":["深钻","深挖","深耕","深掘"],"answer":2,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选C。","__sub":"片段阅读"},{"id":"yy-19284","module":"yanyu","diff":3,"exam":"省考","prompt":"今年以来，绿水青山就是金山银山，老党员代代接力______绿色生态。","options":["守望","守护","看守","守候"],"answer":1,"explanation":"「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选B。","__sub":"选词填空"},{"id":"yy-19285","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，靠山吃山靠水吃水，博物馆讲解员因地制宜______资源优势。","options":["发挥","发扬","施展","发展"],"answer":0,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选A。","__sub":"选词填空"},{"id":"yy-19286","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，营商环境就是生产力，工程师让企业成长有沃土。","options":["培育","培植","厚植","培养"],"answer":2,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选C。","__sub":"片段阅读"},{"id":"yy-19287","module":"yanyu","diff":2,"exam":"事业编","prompt":"近期，减税降费政策落地，工程师让企业真切感受到红利。","options":["发射","发放","散发","释放"],"answer":3,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选D。","__sub":"片段阅读"},{"id":"yy-19288","module":"yanyu","diff":1,"exam":"国考","prompt":"眼下，老厂房变身文创园，消防员让工业遗存______新的活力。","options":["更新","焕新","焕发","换发"],"answer":2,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选C。","__sub":"选词填空"},{"id":"yy-19289","module":"yanyu","diff":1,"exam":"省考","prompt":"近期，减税降费政策落地，法官让企业真切感受到红利。","options":["发放","发射","散发","释放"],"answer":3,"explanation":"「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选D。","__sub":"片段阅读"},{"id":"yy-19290","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，古城修缮不搞大拆大建，老党员让千年文脉在街巷间静静流淌。","options":["延续","接通","续接","连接"],"answer":0,"explanation":"「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选A。","__sub":"片段阅读"},{"id":"yy-19291","module":"yanyu","diff":1,"exam":"教师编","prompt":"盛夏时节，越是众声喧哗，越需要______共识，程序员把大家的心拢到一起。","options":["凝固","凝聚","凝结","冻住"],"answer":1,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选B。","__sub":"选词填空"},{"id":"yy-19292","module":"yanyu","diff":1,"exam":"国考","prompt":"近年来，脱贫不是终点，文旅部门多措并举______脱贫成果。","options":["巩固","加固","稳固","凝固"],"answer":0,"explanation":"「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。","__sub":"选词填空"},{"id":"yy-19293","module":"yanyu","diff":1,"exam":"国考","prompt":"盛夏时节，安全底线不可逾越，老党员24小时轮班值守。","options":["坚守","看守","把守","镇守"],"answer":0,"explanation":"「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选A。","__sub":"片段阅读"},{"id":"yy-19294","module":"yanyu","diff":1,"exam":"省考","prompt":"近期，让农产品出村进城，税务干部多方合力______销售通道。","options":["扩宽","开宽","拓宽","开辟"],"answer":2,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选C。","__sub":"选词填空"},{"id":"yy-19295","module":"yanyu","diff":3,"exam":"省考","prompt":"这些年，急难险重任务面前，社区规划师主动______最重的责任。","options":["抬起","背起","挑起","扛起"],"answer":3,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。","__sub":"选词填空"},{"id":"yy-19296","module":"yanyu","diff":1,"exam":"国考","prompt":"今年以来，人才是创新的第一资源，民警把发展根基越培越厚。","options":["厚植","培土","施肥","浇灌"],"answer":0,"explanation":"「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选A。","__sub":"片段阅读"},{"id":"yy-19297","module":"yanyu","diff":2,"exam":"医疗编","prompt":"近期，靠山吃山靠水吃水，医护人员因地制宜______资源优势。","options":["发扬","发挥","施展","发展"],"answer":1,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选B。","__sub":"选词填空"},{"id":"yy-19298","module":"yanyu","diff":2,"exam":"国考","prompt":"连日来，二十年只做一件事，民警在细分领域里做到极致。","options":["深钻","深耕","深挖","深掘"],"answer":1,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选B。","__sub":"片段阅读"},{"id":"yy-19299","module":"yanyu","diff":2,"exam":"省考","prompt":"盛夏时节，一年一度的民生大考结束，公交司机向群众______了温暖的答卷。","options":["上缴","交出","递交","呈报"],"answer":1,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选B。","__sub":"选词填空"},{"id":"yy-19300","module":"yanyu","diff":2,"exam":"事业编","prompt":"眼下，城乡公共服务仍有落差，程序员以实策逐步______差距。","options":["缩小","减少","缩减","减小"],"answer":0,"explanation":"「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选A。","__sub":"选词填空"},{"id":"yy-19301","module":"yanyu","diff":2,"exam":"国考","prompt":"连日来，老艺人收徒授艺，让千年技艺薪火。","options":["传递","互传","递送","相传"],"answer":3,"explanation":"「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选D。","__sub":"片段阅读"},{"id":"yy-19302","module":"yanyu","diff":3,"exam":"事业编","prompt":"连日来，安全底线不可逾越，非遗传承人24小时轮班值守。","options":["镇守","坚守","把守","看守"],"answer":1,"explanation":"「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选B。","__sub":"片段阅读"},{"id":"yy-19303","module":"yanyu","diff":1,"exam":"省考","prompt":"近年来，一二三产融合发展，法官推动产业链不断延伸。","options":["伸长","拉长","延伸","延长"],"answer":2,"explanation":"「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选C。","__sub":"片段阅读"},{"id":"yy-19304","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，放宽准入激发创业热情，市场监管部门让创造活力。","options":["淌出","涌流","涌出","流出"],"answer":1,"explanation":"「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选B。","__sub":"片段阅读"},{"id":"yy-19305","module":"yanyu","diff":2,"exam":"教师编","prompt":"近年来，跳出一时一地看发展，环卫工人着力______开放共赢的新格局。","options":["搭造","构建","架造","构作"],"answer":1,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选B。","__sub":"选词填空"},{"id":"yy-19306","module":"yanyu","diff":2,"exam":"国考","prompt":"初秋时节，一网通办让数据多跑路，驻村干部以流程再造______政务效能。","options":["提升","拔高","提高","抬高"],"answer":0,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选A。","__sub":"选词填空"},{"id":"yy-19307","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，万丈高楼平地起，果农一锤一钎______发展基础。","options":["填实","夯实","砸实","踩实"],"answer":1,"explanation":"「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选B。","__sub":"选词填空"},{"id":"yy-19308","module":"yanyu","diff":2,"exam":"省考","prompt":"初秋时节，二十年只做一件事，工程师在细分领域里做到极致。","options":["深钻","深耕","深掘","深挖"],"answer":1,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选B。","__sub":"片段阅读"},{"id":"yy-19309","module":"yanyu","diff":3,"exam":"国考","prompt":"岁末年初，手握核心技术专利，渔民创新的底气。","options":["更强","更足","更硬","更壮"],"answer":1,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选B。","__sub":"片段阅读"},{"id":"yy-19310","module":"yanyu","diff":2,"exam":"事业编","prompt":"盛夏时节，订单排到明年，图书管理员发展的信心。","options":["倍加","倍受","加倍","倍增"],"answer":3,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19311","module":"yanyu","diff":1,"exam":"医疗编","prompt":"入冬以来，把资源优势变成产业优势，文旅部门下大气力______区域品牌。","options":["拍打","打造","打制","锻打"],"answer":1,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选B。","__sub":"选词填空"},{"id":"yy-19312","module":"yanyu","diff":2,"exam":"教师编","prompt":"近期，二十年只做一件事，教师在细分领域里做到极致。","options":["深耕","深钻","深挖","深掘"],"answer":0,"explanation":"「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选A。","__sub":"片段阅读"},{"id":"yy-19313","module":"yanyu","diff":3,"exam":"事业编","prompt":"盛夏时节，危难时刻冲得上去，手工艺人的行动______了共产党员的担当。","options":["彰显","显摆","显露","暴露"],"answer":0,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选A。","__sub":"选词填空"},{"id":"yy-19314","module":"yanyu","diff":1,"exam":"教师编","prompt":"连日来，市场细胞活跃起来，广大建设者让经济肌体活力。","options":["塞满","装满","充满","填满"],"answer":2,"explanation":"「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选C。","__sub":"片段阅读"},{"id":"yy-19315","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，急难险重任务面前，果农主动______最重的责任。","options":["扛起","背起","挑起","抬起"],"answer":0,"explanation":"「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-19316","module":"yanyu","diff":1,"exam":"国考","prompt":"今年以来，乡情是最深的牵挂，法官以商会为平台______情感纽带。","options":["捆牢","绑牢","系牢","织牢"],"answer":3,"explanation":"「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选D。","__sub":"选词填空"},{"id":"yy-19317","module":"yanyu","diff":1,"exam":"省考","prompt":"近年来，跳出一时一地看发展，护林员着力______开放共赢的新格局。","options":["搭造","构建","架造","构作"],"answer":1,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选B。","__sub":"选词填空"},{"id":"yy-19318","module":"yanyu","diff":2,"exam":"事业编","prompt":"开春以来，让农产品出村进城，消防员多方合力______销售通道。","options":["开辟","拓宽","开宽","扩宽"],"answer":1,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选B。","__sub":"选词填空"},{"id":"yy-19319","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，景区客流高峰来临，环卫工人全员上岗______游览秩序。","options":["维持","护卫","保护","维护"],"answer":3,"explanation":"「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选D。","__sub":"选词填空"},{"id":"yy-19320","module":"yanyu","diff":1,"exam":"省考","prompt":"一段时间以来，众人的事情由众人商量，治沙工人把各方______到规划图上。","options":["凝聚","聚拢","收拢","归拢"],"answer":0,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选A。","__sub":"选词填空"},{"id":"yy-19321","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，把资源优势变成产业优势，社区工作者下大气力______区域品牌。","options":["拍打","锻打","打造","打制"],"answer":2,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选C。","__sub":"选词填空"},{"id":"yy-19322","module":"yanyu","diff":2,"exam":"医疗编","prompt":"初秋时节，民生领域还有欠账，调解员列出清单逐项______短板。","options":["补齐","贴补","修补","补丁"],"answer":0,"explanation":"「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选A。","__sub":"选词填空"},{"id":"yy-19323","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，人才是创新的第一资源，工程师把发展根基越培越厚。","options":["施肥","浇灌","培土","厚植"],"answer":3,"explanation":"「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选D。","__sub":"片段阅读"},{"id":"yy-19324","module":"yanyu","diff":2,"exam":"事业编","prompt":"今年以来，众人的事情由众人商量，图书管理员把各方______到规划图上。","options":["归拢","收拢","凝聚","聚拢"],"answer":2,"explanation":"「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选C。","__sub":"选词填空"},{"id":"yy-19325","module":"yanyu","diff":2,"exam":"事业编","prompt":"开春以来，政府、市场、社会同向发力，执法人员让各方______成强大合力。","options":["汇集","聚合","汇合","汇聚"],"answer":3,"explanation":"「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选D。","__sub":"选词填空"},{"id":"yy-19326","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，订单排到明年，民警发展的信心。","options":["加倍","倍加","倍受","倍增"],"answer":3,"explanation":"「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19327","module":"yanyu","diff":3,"exam":"事业编","prompt":"近年来，把监督防线扎到最基层，社区规划师走村入户听民声。","options":["织厚","缝密","织密","织补"],"answer":2,"explanation":"「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选C。","__sub":"片段阅读"},{"id":"yy-19328","module":"yanyu","diff":3,"exam":"国考","prompt":"一段时间以来，邻里纠纷无小事，审计人员用真心______一件件矛盾。","options":["瓦解","消融","化解","解开"],"answer":2,"explanation":"「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选C。","__sub":"选词填空"},{"id":"yy-19329","module":"yanyu","diff":3,"exam":"省考","prompt":"今年以来，手握核心技术专利，环卫工人创新的底气。","options":["更硬","更壮","更足","更强"],"answer":2,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选C。","__sub":"片段阅读"},{"id":"yy-19330","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，邻里纠纷无小事，治沙工人用真心______一件件矛盾。","options":["解开","消融","瓦解","化解"],"answer":3,"explanation":"「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选D。","__sub":"选词填空"},{"id":"yy-19331","module":"yanyu","diff":1,"exam":"国考","prompt":"眼下，新区建设的宏伟蓝图已经展开，调解员正把一张张蓝图变成施工图。","options":["编织","修筑","绘就","耕耘"],"answer":2,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选C。","__sub":"片段阅读"},{"id":"yy-19332","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，危难时刻冲得上去，快递员的行动______了共产党员的担当。","options":["显摆","显露","彰显","暴露"],"answer":2,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选C。","__sub":"选词填空"},{"id":"yy-19333","module":"yanyu","diff":2,"exam":"事业编","prompt":"开春以来，汛期将至，社区规划师对辖区地质灾害隐患逐点______。","options":["检查","排查","检察","普查"],"answer":1,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选B。","__sub":"选词填空"},{"id":"yy-19334","module":"yanyu","diff":2,"exam":"事业编","prompt":"一段时间以来，邻里纠纷无小事，非遗传承人用真心______一件件矛盾。","options":["解开","瓦解","消融","化解"],"answer":3,"explanation":"「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选D。","__sub":"选词填空"},{"id":"yy-19335","module":"yanyu","diff":2,"exam":"事业编","prompt":"盛夏时节，营商环境就是生产力，教师让企业成长有沃土。","options":["培育","厚植","培养","培植"],"answer":1,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选B。","__sub":"片段阅读"},{"id":"yy-19336","module":"yanyu","diff":1,"exam":"事业编","prompt":"一段时间以来，汛期将至，图书管理员对辖区地质灾害隐患逐点______。","options":["普查","检查","检察","排查"],"answer":3,"explanation":"「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选D。","__sub":"选词填空"},{"id":"yy-19337","module":"yanyu","diff":1,"exam":"国考","prompt":"连日来，传统村落保护性开发，博物馆讲解员既富了口袋，也______了乡愁。","options":["扣留","留住","截留","拘留"],"answer":1,"explanation":"「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选B。","__sub":"选词填空"},{"id":"yy-19338","module":"yanyu","diff":3,"exam":"事业编","prompt":"今年以来，产业发展的根基越牢，抗风险的能力就越强，设计师深谙此理，先把根基打扎实。","options":["夯实","铺设","敲打","垒砌"],"answer":0,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选A。","__sub":"片段阅读"},{"id":"yy-19339","module":"yanyu","diff":1,"exam":"省考","prompt":"近期，万丈高楼平地起，图书管理员一锤一钎______发展基础。","options":["夯实","砸实","填实","踩实"],"answer":0,"explanation":"「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选A。","__sub":"选词填空"},{"id":"yy-19340","module":"yanyu","diff":1,"exam":"省考","prompt":"连日来，齐抓共管不是一句口号，非遗传承人推动齐抓共管合力。","options":["成立","成型","形成","成形"],"answer":2,"explanation":"「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选C。","__sub":"片段阅读"},{"id":"yy-19341","module":"yanyu","diff":3,"exam":"医疗编","prompt":"连日来，小哨兵大作用，教师让基层网格______更大作用。","options":["施展","发扬","发挥","表现"],"answer":2,"explanation":"「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选C。","__sub":"选词填空"},{"id":"yy-19342","module":"yanyu","diff":2,"exam":"国考","prompt":"入冬以来，手握核心技术专利，铁路养护工创新的底气。","options":["更硬","更壮","更足","更强"],"answer":2,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选C。","__sub":"片段阅读"},{"id":"yy-19343","module":"yanyu","diff":3,"exam":"教师编","prompt":"盛夏时节，靠山吃山靠水吃水，调解员因地制宜______资源优势。","options":["施展","发挥","发展","发扬"],"answer":1,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选B。","__sub":"选词填空"},{"id":"yy-19344","module":"yanyu","diff":1,"exam":"事业编","prompt":"连日来，市场不是法外之地，铁路养护工以制度______交易秩序。","options":["规范","规定","规整","规正"],"answer":0,"explanation":"「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选A。","__sub":"选词填空"},{"id":"yy-19345","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，金杯银杯不如老百姓的口碑，图书管理员把每件小事都当大事办。","options":["设立","建立","创立","树立"],"answer":3,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19346","module":"yanyu","diff":3,"exam":"省考","prompt":"岁末年初，跳出一时一地看发展，快递员着力______开放共赢的新格局。","options":["架造","搭造","构作","构建"],"answer":3,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选D。","__sub":"选词填空"},{"id":"yy-19347","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，在广袤乡野间，基层干部用汗水______出乡村振兴的崭新篇章。","options":["誊写","描红","抄写","书写"],"answer":3,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选D。","__sub":"选词填空"},{"id":"yy-19348","module":"yanyu","diff":2,"exam":"国考","prompt":"近期，向存量要效益，博物馆讲解员为产业升级______新空间。","options":["拓展","展开","拓开","开展"],"answer":0,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选A。","__sub":"选词填空"},{"id":"yy-19349","module":"yanyu","diff":2,"exam":"省考","prompt":"开春以来，越是众声喧哗，越需要______共识，渔民把大家的心拢到一起。","options":["凝聚","凝固","冻住","凝结"],"answer":0,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选A。","__sub":"选词填空"},{"id":"yy-19350","module":"yanyu","diff":2,"exam":"事业编","prompt":"初秋时节，纪律规矩挺在前面，市场监管部门始终______纪律底线。","options":["看守","遵守","严守","把守"],"answer":2,"explanation":"「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选C。","__sub":"选词填空"},{"id":"yy-19351","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，手握核心技术专利，设计师创新的底气。","options":["更硬","更壮","更足","更强"],"answer":2,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选C。","__sub":"片段阅读"},{"id":"yy-19352","module":"yanyu","diff":3,"exam":"国考","prompt":"近期，手握核心技术专利，护林员创新的底气。","options":["更硬","更足","更强","更壮"],"answer":1,"explanation":"「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选B。","__sub":"片段阅读"},{"id":"yy-19353","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，营商环境就是生产力，网格员让企业成长有沃土。","options":["培育","厚植","培养","培植"],"answer":1,"explanation":"「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选B。","__sub":"片段阅读"},{"id":"yy-19354","module":"yanyu","diff":1,"exam":"国考","prompt":"入冬以来，誓师大会上，调解员精神斗志，誓言响彻训练场。","options":["昂扬","高涨","高扬","高昂"],"answer":0,"explanation":"「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19355","module":"yanyu","diff":3,"exam":"国考","prompt":"开春以来，让公共服务覆盖城乡，手工艺人持续______政策体系。","options":["补完","修完","完善","完缮"],"answer":2,"explanation":"「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选C。","__sub":"选词填空"},{"id":"yy-19356","module":"yanyu","diff":1,"exam":"事业编","prompt":"连日来，跳出一时一地看发展，非遗传承人着力______开放共赢的新格局。","options":["构作","构建","架造","搭造"],"answer":1,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选B。","__sub":"选词填空"},{"id":"yy-19357","module":"yanyu","diff":2,"exam":"国考","prompt":"今年以来，一揽子政策精准落地，青年学子着力______市场信心。","options":["提起","振作","提振","鼓动"],"answer":2,"explanation":"「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选C。","__sub":"选词填空"},{"id":"yy-19358","module":"yanyu","diff":1,"exam":"省考","prompt":"近期，改革到了深水区，社区工作者以钉钉子精神______工作局面。","options":["翻开","打开","揭开","掀开"],"answer":1,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选B。","__sub":"选词填空"},{"id":"yy-19359","module":"yanyu","diff":1,"exam":"省考","prompt":"这些年，产业发展的根基越牢，抗风险的能力就越强，基层干部深谙此理，先把根基打扎实。","options":["夯实","敲打","垒砌","铺设"],"answer":0,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选A。","__sub":"片段阅读"},{"id":"yy-19360","module":"yanyu","diff":1,"exam":"教师编","prompt":"入冬以来，把监督防线扎到最基层，环卫工人走村入户听民声。","options":["织补","织密","缝密","织厚"],"answer":1,"explanation":"「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选B。","__sub":"片段阅读"},{"id":"yy-19361","module":"yanyu","diff":1,"exam":"国考","prompt":"近期，越是爬坡过坎，越要______必胜信心，非遗传承人一步一个脚印向前走。","options":["坚持不懈","坚强","坚决","坚定"],"answer":3,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选D。","__sub":"选词填空"},{"id":"yy-19362","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，改革红利持续显现，市场活力不断，环卫工人信心更足。","options":["爆发","突发","暴发","迸发"],"answer":3,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选D。","__sub":"片段阅读"},{"id":"yy-19363","module":"yanyu","diff":3,"exam":"医疗编","prompt":"近年来，传统村落保护性开发，图书管理员既富了口袋，也______了乡愁。","options":["扣留","拘留","留住","截留"],"answer":2,"explanation":"「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选C。","__sub":"选词填空"},{"id":"yy-19364","module":"yanyu","diff":2,"exam":"省考","prompt":"这些年，危难时刻冲得上去，设计师的行动______了共产党员的担当。","options":["彰显","显露","暴露","显摆"],"answer":0,"explanation":"「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选A。","__sub":"选词填空"},{"id":"yy-19365","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，越是众声喧哗，越需要______共识，设计师把大家的心拢到一起。","options":["凝固","冻住","凝结","凝聚"],"answer":3,"explanation":"「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选D。","__sub":"选词填空"},{"id":"yy-19366","module":"yanyu","diff":3,"exam":"省考","prompt":"入冬以来，新区建设的宏伟蓝图已经展开，治沙工人正把一张张蓝图变成施工图。","options":["绘就","修筑","编织","耕耘"],"answer":0,"explanation":"「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选A。","__sub":"片段阅读"},{"id":"yy-19367","module":"yanyu","diff":2,"exam":"国考","prompt":"眼下，把资源优势变成产业优势，审计人员下大气力______区域品牌。","options":["拍打","打造","打制","锻打"],"answer":1,"explanation":"「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选B。","__sub":"选词填空"},{"id":"yy-19368","module":"yanyu","diff":3,"exam":"事业编","prompt":"这些年，夜市灯火点亮街巷，社区工作者为城市______了烟火活力。","options":["增加","增添","增补","追加"],"answer":1,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选B。","__sub":"选词填空"},{"id":"yy-19369","module":"yanyu","diff":2,"exam":"事业编","prompt":"岁末年初，把风险挺在前面，市场监管部门织密织牢安全网。","options":["提防","防范","防守","防备"],"answer":1,"explanation":"「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选B。","__sub":"片段阅读"},{"id":"yy-19370","module":"yanyu","diff":2,"exam":"事业编","prompt":"近期，让农产品出村进城，非遗传承人多方合力______销售通道。","options":["扩宽","开宽","拓宽","开辟"],"answer":2,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选C。","__sub":"选词填空"},{"id":"yy-19371","module":"yanyu","diff":3,"exam":"国考","prompt":"岁末年初，改革到了深水区，公交司机以钉钉子精神______工作局面。","options":["打开","掀开","揭开","翻开"],"answer":0,"explanation":"「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选A。","__sub":"选词填空"},{"id":"yy-19372","module":"yanyu","diff":3,"exam":"国考","prompt":"这些年，安全底线不可逾越，工程师24小时轮班值守。","options":["坚守","镇守","把守","看守"],"answer":0,"explanation":"「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选A。","__sub":"片段阅读"},{"id":"yy-19373","module":"yanyu","diff":2,"exam":"国考","prompt":"开春以来，金杯银杯不如老百姓的口碑，民警把每件小事都当大事办。","options":["树立","创立","建立","设立"],"answer":0,"explanation":"「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19374","module":"yanyu","diff":1,"exam":"省考","prompt":"一段时间以来，一网通办让数据多跑路，基层干部以流程再造______政务效能。","options":["提高","提升","抬高","拔高"],"answer":1,"explanation":"「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选B。","__sub":"选词填空"},{"id":"yy-19375","module":"yanyu","diff":3,"exam":"省考","prompt":"一段时间以来，在广袤乡野间，工程师用汗水______出乡村振兴的崭新篇章。","options":["描红","书写","抄写","誊写"],"answer":1,"explanation":"「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选B。","__sub":"选词填空"},{"id":"yy-19376","module":"yanyu","diff":1,"exam":"事业编","prompt":"连日来，老厂房变身文创园，民警让工业遗存______新的活力。","options":["换发","焕新","更新","焕发"],"answer":3,"explanation":"「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选D。","__sub":"选词填空"},{"id":"yy-19377","module":"yanyu","diff":3,"exam":"事业编","prompt":"盛夏时节，越是爬坡过坎，越要______必胜信心，博物馆讲解员一步一个脚印向前走。","options":["坚强","坚定","坚决","坚持不懈"],"answer":1,"explanation":"「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选B。","__sub":"选词填空"},{"id":"yy-19378","module":"yanyu","diff":1,"exam":"省考","prompt":"这些年，把消费潜力转化为增长实绩，民警拿出了实招硬招。","options":["散发","喷发","释放","发泄"],"answer":2,"explanation":"「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选C。","__sub":"片段阅读"},{"id":"yy-19379","module":"yanyu","diff":1,"exam":"国考","prompt":"连日来，跳出一时一地看发展，设计师着力______开放共赢的新格局。","options":["搭造","构作","架造","构建"],"answer":3,"explanation":"「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选D。","__sub":"选词填空"},{"id":"yy-19380","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，产业发展的根基越牢，抗风险的能力就越强，调解员深谙此理，先把根基打扎实。","options":["垒砌","敲打","夯实","铺设"],"answer":2,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选C。","__sub":"片段阅读"},{"id":"yy-19381","module":"yanyu","diff":1,"exam":"事业编","prompt":"近期，老艺人收徒授艺，让千年技艺薪火。","options":["传递","互传","相传","递送"],"answer":2,"explanation":"「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选C。","__sub":"片段阅读"},{"id":"yy-19382","module":"yanyu","diff":1,"exam":"省考","prompt":"一段时间以来，把监督防线扎到最基层，铁路养护工走村入户听民声。","options":["织补","织厚","织密","缝密"],"answer":2,"explanation":"「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选C。","__sub":"片段阅读"},{"id":"yy-19383","module":"yanyu","diff":3,"exam":"国考","prompt":"近年来，产业发展的根基越牢，抗风险的能力就越强，审计人员深谙此理，先把根基打扎实。","options":["垒砌","夯实","敲打","铺设"],"answer":1,"explanation":"「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选B。","__sub":"片段阅读"},{"id":"yy-19384","module":"yanyu","diff":2,"exam":"国考","prompt":"盛夏时节，改革红利持续显现，市场活力不断，社区规划师信心更足。","options":["暴发","迸发","突发","爆发"],"answer":1,"explanation":"「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选B。","__sub":"片段阅读"},{"id":"yy-19385","module":"yanyu","diff":1,"exam":"国考","prompt":"连日来，让农产品出村进城，执法人员多方合力______销售通道。","options":["开辟","开宽","拓宽","扩宽"],"answer":2,"explanation":"「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选C。","__sub":"选词填空"},{"id":"yy-19386","module":"yanyu","diff":2,"exam":"国考","prompt":"岁末年初，夜市灯火点亮街巷，科研人员为城市______了烟火活力。","options":["增加","增补","追加","增添"],"answer":3,"explanation":"「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选D。","__sub":"选词填空"},{"id":"yy-19387","module":"yanyu","diff":2,"exam":"省考","prompt":"今年以来，一年一度的民生大考结束，广大建设者向群众______了温暖的答卷。","options":["交出","上缴","递交","呈报"],"answer":0,"explanation":"「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选A。","__sub":"选词填空"},{"id":"yy-19388","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，春潮拍岸千帆竞，铁路养护工感受到创新活力。","options":["流出","涌出","涌动","淌动"],"answer":2,"explanation":"「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选C。","__sub":"片段阅读"},{"id":"yy-19389","module":"yanyu","diff":3,"exam":"国考","prompt":"眼下，停车难是城市治理的老大难，市场监管部门用共享思维______了这一难题。","options":["解冻","解释","破解","解开"],"answer":2,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选C。","__sub":"选词填空"},{"id":"yy-19390","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，把家国情怀融入课堂，市场监管部门用身边故事打动学生。","options":["培土","浇灌","施肥","厚植"],"answer":3,"explanation":"「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选D。","__sub":"片段阅读"},{"id":"yy-19391","module":"yanyu","diff":1,"exam":"教师编","prompt":"一段时间以来，民生实事清单公示上墙，调解员一件一件______承诺。","options":["实现","兑现","完成","达成"],"answer":1,"explanation":"「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选B。","__sub":"选词填空"},{"id":"yy-19392","module":"yanyu","diff":1,"exam":"教师编","prompt":"这些年，把家国情怀融入课堂，科研人员用身边故事打动学生。","options":["厚植","施肥","培土","浇灌"],"answer":0,"explanation":"「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选A。","__sub":"片段阅读"},{"id":"yy-19393","module":"yanyu","diff":2,"exam":"事业编","prompt":"这些年，靠山吃山靠水吃水，果农因地制宜______资源优势。","options":["发展","施展","发扬","发挥"],"answer":3,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选D。","__sub":"选词填空"},{"id":"yy-19394","module":"yanyu","diff":2,"exam":"教师编","prompt":"岁末年初，从受理到反馈全流程留痕，基层干部以数字化手段______管理闭环。","options":["构建","圈画","构画","搭圈"],"answer":0,"explanation":"「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选A。","__sub":"选词填空"},{"id":"yy-19395","module":"yanyu","diff":2,"exam":"事业编","prompt":"连日来，靠山吃山靠水吃水，快递员因地制宜______资源优势。","options":["施展","发挥","发展","发扬"],"answer":1,"explanation":"「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选B。","__sub":"选词填空"},{"id":"yy-19396","module":"yanyu","diff":3,"exam":"省考","prompt":"近年来，向存量要效益，社区规划师为产业升级______新空间。","options":["拓展","开展","展开","拓开"],"answer":0,"explanation":"「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选A。","__sub":"选词填空"},{"id":"yy-19397","module":"yanyu","diff":1,"exam":"省考","prompt":"初秋时节，让新业态释放新动能，执法人员在制度创新上先行先试。","options":["引爆","点燃","发动","激发"],"answer":3,"explanation":"「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选D。","__sub":"片段阅读"},{"id":"yy-19398","module":"yanyu","diff":2,"exam":"医疗编","prompt":"一段时间以来，面对转型路上的重重难关，治沙工人迎难而上，把一个个难关逐一______。","options":["攻克","克服","破除","化解"],"answer":0,"explanation":"「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选A。","__sub":"选词填空"},{"id":"yy-19399","module":"yanyu","diff":2,"exam":"国考","prompt":"近年来，停车难是城市治理的老大难，网格员用共享思维______了这一难题。","options":["解释","解开","解冻","破解"],"answer":3,"explanation":"「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选D。","__sub":"选词填空"},{"id":"yy-19400","module":"yanyu","diff":2,"exam":"国考","prompt":"这些年，春潮拍岸千帆竞，快递员感受到创新活力。","options":["涌动","淌动","流出","涌出"],"answer":0,"explanation":"「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选A。","__sub":"片段阅读"},{"id":"yy-19401","module":"yanyu","diff":1,"exam":"事业编","prompt":"百年老铺上线外卖平台，联名新品月月上新。年轻设计师操刀包装，门店焕新保留记忆。老掌柜坦言，手艺有了传人。\n\n最适合做这段文字标题的是：","options":["老字号应全面网红化","老字号应原封不动","老字号只靠情怀","老字号传承需在坚守品质基础上创新表达"],"answer":3,"explanation":"文段以「老字号焕新」为背景，落脚点在「老字号焕新要在守正与创新间找到平衡。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选D。","__sub":"片段阅读"},{"id":"yy-19402","module":"yanyu","diff":2,"exam":"国考","prompt":"游戏平台上线人脸识别，可疑账号二次验证。家长监护平台使用率上升，亲子公约共同签署。教育专家提醒，堵疏结合才是正道。\n\n作者通过这段文字意在强调：","options":["禁网即可解决问题","孩子自控力无需引导","防沉迷形同虚设","防沉迷需要技术手段与家庭陪伴双管齐下"],"answer":3,"explanation":"文段以「防沉迷」为背景，落脚点在「未成年人网络保护需要技术、家庭与社会协同。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选D。","__sub":"片段阅读"},{"id":"yy-19403","module":"yanyu","diff":2,"exam":"教师编","prompt":"小区撤桶并点后，楼道公示分类红黑榜。志愿者在投放点值守，误投者现场指导纠正。半年过去，厨余垃圾分出率大幅提升。\n\n作者通过这段文字意在强调：","options":["垃圾分类推广贵在习惯养成与持续引导","分类准确率无关紧要","垃圾分类主要靠罚款","垃圾分类是环卫部门的事"],"answer":0,"explanation":"文段以「垃圾分类」为背景，落脚点在「习惯养成需要引导与约束并重，久久为功。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选A。","__sub":"片段阅读"},{"id":"yy-19404","module":"yanyu","diff":3,"exam":"国考","prompt":"一件事一次办改革推开，表单合并一表申请。窗口人员从专科受理变全科服务，后台并联审批。企业主感受直观，把时间还给经营。\n\n作者通过这段文字意在强调：","options":["改革应增加申报材料","线上办理可完全取代线下","跨部门流程再造提升政务服务效能","审批越慢越严谨"],"answer":2,"explanation":"文段以「政务服务」为背景，落脚点在「政务服务改革的核心是流程再造与数据共享。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选C。","__sub":"片段阅读"},{"id":"yy-19405","module":"yanyu","diff":2,"exam":"教师编","prompt":"滴灌带铺进大田，水肥一体化精准滴灌。水价改革倒逼节水，定额管理到户。种植户算账，成本两年收回。\n\n作者通过这段文字意在强调：","options":["农业节水是技术改造与机制创新的结合","节水是政府的事","节水就是少浇水","节水与产量矛盾"],"answer":0,"explanation":"文段以「节水农业」为背景，落脚点在「农业节水要靠技术、价格与种植结构协同。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选A。","__sub":"片段阅读"},{"id":"yy-19406","module":"yanyu","diff":2,"exam":"事业编","prompt":"沿河两岸的废弃铁路线被改造成绿道，保留沿线老树与铁轨记忆。市民骑车或步行其间，串起菜市场、老公园和新建的体育角，早晚锻炼的人流络绎不绝。规划部门表示，智慧导览系统即将上线。\n\n这段文字主要说明：","options":["机动车道应全部改建为绿道","绿道建设应优先服务游客","绿道建设让公共空间连通成网、惠及日常","绿道维护成本高不宜推广"],"answer":2,"explanation":"文段以「城市绿道」为背景，落脚点在「绿道把零散公共空间连成整体，让城市生活更宜居。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选C。","__sub":"片段阅读"},{"id":"yy-19407","module":"yanyu","diff":1,"exam":"事业编","prompt":"一件事一次办改革推开，表单合并一表申请。窗口人员从专科受理变全科服务，电子证照互认。企业主感受直观，把时间还给经营。\n\n最适合做这段文字标题的是：","options":["线上办理可完全取代线下","跨部门流程再造提升政务服务效能","政务服务就是多设窗口","改革应增加申报材料"],"answer":1,"explanation":"文段以「政务服务」为背景，落脚点在「政务服务改革的核心是流程再造与数据共享。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选B。","__sub":"片段阅读"},{"id":"yy-19408","module":"yanyu","diff":3,"exam":"国考","prompt":"百年老铺上线外卖平台，招牌菜扫码看故事。年轻设计师操刀包装，短视频讲述技艺。老掌柜坦言，年轻人回来了。\n\n最适合做这段文字标题的是：","options":["老字号传承需在坚守品质基础上创新表达","老字号应全面网红化","老字号注定被淘汰","老字号应原封不动"],"answer":0,"explanation":"文段以「老字号焕新」为背景，落脚点在「老字号焕新要在守正与创新间找到平衡。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选A。","__sub":"片段阅读"},{"id":"yy-19409","module":"yanyu","diff":2,"exam":"国考","prompt":"一件事一次办改革推开，材料精简过半。窗口人员从专科受理变全科服务，电子证照互认。企业主感受直观，开办企业当天拿照。\n\n这段文字主要说明：","options":["跨部门流程再造提升政务服务效能","改革应增加申报材料","政务服务就是多设窗口","线上办理可完全取代线下"],"answer":0,"explanation":"文段以「政务服务」为背景，落脚点在「政务服务改革的核心是流程再造与数据共享。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选A。","__sub":"片段阅读"},{"id":"yy-19410","module":"yanyu","diff":1,"exam":"国考","prompt":"退养还湿工程推进，养殖围网全面清理。监测显示候鸟种群回升，鸟类记录刷新历史。保护区管理者说，科研监测支撑决策。\n\n最适合做这段文字标题的是：","options":["候鸟增多与保护无关","湿地保护应禁止一切活动","修复一次即可一劳永逸","生态修复是系统工程，成效来自持续治理"],"answer":3,"explanation":"文段以「湿地保护」为背景，落脚点在「生态修复需要系统治理与久久为功。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选D。","__sub":"片段阅读"},{"id":"yy-19411","module":"yanyu","diff":3,"exam":"省考","prompt":"纺织老厂变身设计园区，锯齿形屋顶引入天光。老车间保留桁架与标语，机器零件变成雕塑。园区运营方介绍，老职工回园区再就业。\n\n最适合做这段文字标题的是：","options":["工业遗存活化应兼顾记忆保留与功能再造","改造应推倒重来","老厂房应全部拆除","活化就是开咖啡馆"],"answer":0,"explanation":"文段以「老旧厂房活化」为背景，落脚点在「工业遗存活化利用让城市记忆与产业新生共存。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选A。","__sub":"片段阅读"},{"id":"yy-19412","module":"yanyu","diff":1,"exam":"国考","prompt":"职业院校把课堂搬进车间，学徒制覆盖重点专业。企业工程师驻校授课，真题真做进课堂。毕业生就业率连年攀升，薪酬水平水涨船高。\n\n最适合做这段文字标题的是：","options":["校企合作流于形式","职校应压缩实训课时","技能人才不需要理论","产教融合是职业教育提质培优的必由之路"],"answer":3,"explanation":"文段以「职教改革」为背景，落脚点在「产教融合让技能人才成长与产业需求同频。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选D。","__sub":"片段阅读"},{"id":"yy-19413","module":"yanyu","diff":3,"exam":"国考","prompt":"老住宅楼加装电梯提上日程，一楼住户起初有顾虑。社区搭台让居民协商，请来律师和工程师答疑。电梯落成那天，经验被写进操作指引。\n\n这段文字主要说明：","options":["加梯必须统一标准一刀切","基层协商机制是化解加梯矛盾的关键","物业应主导加梯全部事务","低层住户应无条件同意"],"answer":1,"explanation":"文段以「老楼加梯」为背景，落脚点在「加装电梯难在人心，成在协商，基层自治是关键。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选B。","__sub":"片段阅读"},{"id":"yy-19414","module":"yanyu","diff":2,"exam":"国考","prompt":"社区食堂开进老旧小区，面积不大却窗明几净。一荤两素八块钱，老人刷脸就能就餐，节假日还开设亲子烘焙课。运营方算的是长远账：客流稳定就能微利运营。\n\n作者通过这段文字意在强调：","options":["社区食堂应完全免费向居民开放","社区食堂兼顾公益与可持续，方能长久惠民","社区食堂应全部交由市场定价","社区食堂应停止对外营业"],"answer":1,"explanation":"文段以「社区食堂」为背景，落脚点在「社区食堂以公益属性托底，用可持续运营守护一餐热饭。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选B。","__sub":"片段阅读"},{"id":"yy-19415","module":"yanyu","diff":1,"exam":"省考","prompt":"城市书房开进商圈楼宇，绘本区与咖啡角相邻。借阅与购书数据打通，读者画像精准荐书。馆员观察到，亲子共读成为风尚。\n\n这段文字主要说明：","options":["电子阅读不值得提倡","公共阅读设施布局下沉激活全民阅读","图书馆应只收藏不外借","阅读应回归纸质书"],"answer":1,"explanation":"文段以「书香城市」为背景，落脚点在「公共阅读空间的重构让书香融入日常生活。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选B。","__sub":"片段阅读"},{"id":"yy-19416","module":"yanyu","diff":3,"exam":"国考","prompt":"某市图书馆设立古籍修复中心，配备恒温恒湿设备，培养专职修复师十二名。修复师先为残卷除尘、补纸、托裱，再进行压平、装订，全程影像记录建立修复档案。经过数年努力，修复经验向周边地市推广。\n\n作者通过这段文字意在强调：","options":["古籍修复设备昂贵是最大障碍","古籍修复师收入待遇亟待提高","古籍修复是技术与匠心共同作用的系统工程","图书馆应把重心转向古籍修复"],"answer":2,"explanation":"文段以「古籍修复」为背景，落脚点在「古籍修复既靠技术设备，更靠耐心与传承，让珍贵典籍重获新生。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选C。","__sub":"片段阅读"},{"id":"yy-19417","module":"yanyu","diff":3,"exam":"国考","prompt":"小区撤桶并点后，智能回收箱可积分兑换。志愿者在投放点值守，为老人提供代扔服务。半年过去，资源化利用链条打通。\n\n最适合做这段文字标题的是：","options":["分类桶越多越好","垃圾分类推广贵在习惯养成与持续引导","分类准确率无关紧要","垃圾分类主要靠罚款"],"answer":1,"explanation":"文段以「垃圾分类」为背景，落脚点在「习惯养成需要引导与约束并重，久久为功。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选B。","__sub":"片段阅读"},{"id":"yy-19418","module":"yanyu","diff":1,"exam":"省考","prompt":"老年大学报名火爆，模特队平均年龄六十八。适老化改造走进千家万户，大字版菜单随处可见。相关企业负责人说，适老产品贵在贴心。\n\n最适合做这段文字标题的是：","options":["养老服务供给需贴合老年群体真实需求","养老服务应由子女承担","适老化改造可有可无","老年人消费能力不足"],"answer":0,"explanation":"文段以「银发经济」为背景，落脚点在「银发经济潜力巨大，供给适配是关键。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选A。","__sub":"片段阅读"},{"id":"yy-19419","module":"yanyu","diff":2,"exam":"国考","prompt":"退养还湿工程推进，养殖围网全面清理。监测显示候鸟种群回升，植被覆盖稳步恢复。保护区管理者说，共管机制让渔民转产。\n\n最适合做这段文字标题的是：","options":["修复一次即可一劳永逸","湿地应全部开发旅游","生态修复是系统工程，成效来自持续治理","候鸟增多与保护无关"],"answer":2,"explanation":"文段以「湿地保护」为背景，落脚点在「生态修复需要系统治理与久久为功。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选C。","__sub":"片段阅读"},{"id":"yy-19420","module":"yanyu","diff":1,"exam":"国考","prompt":"改造前先问需于民，意见征集三轮入户。施工期间居民监督员全程在场，进度上墙每周更新。改造后长效管理跟上，物业费收缴率提高了。\n\n作者通过这段文字意在强调：","options":["居民参与和长效管理决定改造成色","改造应一步到位","改造与居民无关","改造后无需管理"],"answer":0,"explanation":"文段以「老旧小区改造」为背景，落脚点在「老旧小区改造既要改硬件，更要建机制。」。正确项是对文段主旨的准确概括；其余选项或无中生有、或以偏概全、或推过度，均不符合文意。故选A。","__sub":"片段阅读"},{"id":"tt-12160","module":"tuitui","prompt":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","fig":"<svg viewBox=\"0 0 100 100\" width=\"100\" height=\"100\"><g stroke=\"#333\" stroke-width=\"2.5\" fill=\"none\"><g transform=\"translate(2.70,2.70) scale(0.28)\"><line x1=\"20\" y1=\"50\" x2=\"80\" y2=\"50\"/></g><g transform=\"translate(36.00,2.70) scale(0.28)\"><line x1=\"20\" y1=\"50\" x2=\"80\" y2=\"50\"/></g><g transform=\"translate(69.30,2.70) scale(0.28)\"><line x1=\"20\" y1=\"50\" x2=\"80\" y2=\"50\"/></g><g transform=\"translate(2.70,36.00) scale(0.28)\"><line x1=\"80\" y1=\"20\" x2=\"20\" y2=\"80\"/></g><g transform=\"translate(36.00,36.00) scale(0.28)\"><line x1=\"80\" y1=\"20\" x2=\"20\" y2=\"80\"/></g><g transform=\"translate(69.30,36.00) scale(0.28)\"><line x1=\"80\" y1=\"20\" x2=\"20\" y2=\"80\"/></g><g transform=\"translate(2.70,69.30) scale(0.28)\"><line x1=\"50\" y1=\"20\" x2=\"50\" y2=\"80\"/><line x1=\"20\" y1=\"50\" x2=\"80\" y2=\"50\"/></g><g transform=\"translate(36.00,69.30) scale(0.28)\"><line x1=\"50\" y1=\"20\" x2=\"50\" y2=\"80\"/><line x1=\"20\" y1=\"50\" x2=\"80\" y2=\"50\"/></g><g transform=\"translate(69.30,69.30) scale(0.28)\"><line x1=\"50\" y1=\"20\" x2=\"50\" y2=\"80\"/><line x1=\"20\" y1=\"50\" x2=\"80\" y2=\"50\"/></g></g></svg>","options":["<svg viewBox=\"0 0 100 100\" width=\"100\" height=\"100\"><g stroke=\"#333\" stroke-width=\"2.5\" fill=\"none\"><line x1=\"50\" y1=\"20\" x2=\"50\" y2=\"80\"/></g></svg>","<svg viewBox=\"0 0 100 100\" width=\"100\" height=\"100\"><g stroke=\"#333\" stroke-width=\"2.5\" fill=\"none\"><line x1=\"50\" y1=\"20\" x2=\"50\" y2=\"80\"/><line x1=\"20\" y1=\"50\" x2=\"80\" y2=\"50\"/></g></svg>","<svg viewBox=\"0 0 100 100\" width=\"100\" height=\"100\"><g stroke=\"#333\" stroke-width=\"2.5\" fill=\"none\"><line x1=\"20\" y1=\"50\" x2=\"80\" y2=\"50\"/></g></svg>","<svg viewBox=\"0 0 100 100\" width=\"100\" height=\"100\"><g stroke=\"#333\" stroke-width=\"2.5\" fill=\"none\"><line x1=\"50\" y1=\"20\" x2=\"50\" y2=\"80\"/></g></svg>"],"answer":1,"explanation":"每行第三幅图由前两幅去异存同：只保留两图中都有的线条，去掉不同的线条。第三行前两幅图叠加后应含2条线条（竖线、横线）。只有正确选项的线条组成与之相符，故选B。","diff":1,"exam":"事业编","__sub":"图形推理"},{"id":"tt-12379","module":"tuitui","prompt":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","fig":"<svg viewBox=\"0 0 100 100\" width=\"100\" height=\"100\"><g stroke=\"#333\" stroke-width=\"2.5\" fill=\"none\"><g transform=\"translate(3.00,39.00) scale(0.22)\"><polygon points=\"32.0,30.0 68.0,30.0 82.0,72.0 18.0,72.0\" fill=\"none\"/></g><g transform=\"translate(27.00,39.00) scale(0.22)\"><polygon points=\"24.0,40.0 76.0,40.0 62.0,74.0 38.0,74.0\" fill=\"none\"/></g><g transform=\"translate(51.00,39.00) scale(0.22)\"><polygon points=\"50.0,20.0 58.0,50.0 50.0,80.0 42.0,50.0\" fill=\"none\"/></g><text x=\"87.5\" y=\"58\" font-size=\"22\" text-anchor=\"middle\" fill=\"#333\" stroke=\"none\">?</text></g></svg>","options":["<svg viewBox=\"0 0 100 100\" width=\"100\" height=\"100\"><g stroke=\"#333\" stroke-width=\"2.5\" fill=\"none\"><polygon points=\"50.0,20.0 58.0,50.0 50.0,80.0 42.0,50.0\" fill=\"none\"/></g></svg>","<svg viewBox=\"0 0 100 100\" width=\"100\" height=\"100\"><g stroke=\"#333\" stroke-width=\"2.5\" fill=\"none\"><polygon points=\"28.0,34.0 76.0,22.0 84.0,66.0 40.0,78.0\" fill=\"none\"/></g></svg>","<svg viewBox=\"0 0 100 100\" width=\"100\" height=\"100\"><g stroke=\"#333\" stroke-width=\"2.5\" fill=\"none\"><polygon points=\"30.0,28.0 78.0,34.0 66.0,76.0 24.0,70.0 44.0,48.0\" fill=\"none\"/></g></svg>","<svg viewBox=\"0 0 100 100\" width=\"100\" height=\"100\"><g stroke=\"#333\" stroke-width=\"2.5\" fill=\"none\"><polygon points=\"36.0,20.0 82.0,48.0 64.0,76.0 18.0,62.0\" fill=\"none\"/></g></svg>"],"answer":0,"explanation":"题干图形都是轴对称图形（沿竖直中线折叠后两侧完全重合），问号处也应为轴对称图形。只有正确选项沿竖直中线对称，其余选项找不到对称轴，故选A。","diff":3,"exam":"省考","__sub":"图形推理"}]);